//! Zero-byte-leakage algebraic `Tower256` multilinear zerocheck + `LogUp256` lookup content
//! certificates (`UD-100` coset Additive-FRI, literally zero position disclosures).
//!
//! Mirrors `Compiler/Tower256AlgebraicCert.lean` byte-for-byte:
//! - Order-`(2^32 - 1)` multiplicative counter subgroup `GF(2^32)^× ⊂ Tower256^×` generated by
//!   `zeta_c = leaf_of_u64(65541)` (`0x10005`, inverse `zeta_inv_c = leaf_of_u64(848_205_651)`),
//!   avoiding characteristic-2 `1 + 1 = 0` wraparound up to `4,294,967,294` steps across
//!   `ClaimData::Accept`, `ClaimData::Count`, and `(d + 1)`-bit zero-count-disclosure
//!   `ClaimData::Bound`.
//! - Half-cube witness blinding `halfCubeExtend(w, u)` on `{0, 1}^{d+1}` (`x_d = 0` witness,
//!   `x_d = 1` uniform `Tower256` mask) committed via Boolean-Möbius additive-novel-basis
//!   evaluation on the disjoint coset `coset_offset(ell) + V_ell` (`coset_offset(ell) = 2^ell`),
//!   where every coset point has non-Boolean masking coordinate `theta_d ∉ {0, 1}`.
//! - Characteristic-2-safe `theta_row`-weighted `LogUp256` lookup argument (`alpha` 4-tuple
//!   Reed–Solomon fingerprint `b + alpha*s + alpha^2*nx + alpha^3*hit`, `theta` per-row power
//!   weights preventing `1 + 1 = 0` forged-pair cancellation, `gamma` rational balance + quadratic
//!   inverse checks) reduced via a `(d + 1)`-round HVZK degree-`<= 4` multilinear sumcheck to 15
//!   masked evaluations at `r = (r_0, ..., r_d)` (`r_d ∉ {0, 1}`).
//! - Coherent `(d + 1)`-round `evalFold` chain from `sum_k eta^k P_k` on `coset_offset(ell) + V_ell`
//!   to constant `v_batch` + `Tower256SuccinctCheck` (`receiptStream`) coset Additive-FRI on
//!   `M_fri + sum_k rho^{k+1} P_k` (`final_degree = 1`, `0` verifier inversions).

use std::sync::atomic::{AtomicU64, Ordering};

use sha3::{
    digest::{ExtendableOutput, Update, XofReader},
    CShake256, CShake256Core,
};

use crate::binary_tower_256::Tower256;
use crate::hash_kernels::cshake256_xof;
use crate::tower256_private_cert::{
    automaton_commit, depth_of, keccak_f_count as base_keccak_f_count, leaf_of_u64,
    reset_keccak_counter as reset_base_keccak_counter, unit_basis, ClaimData, CubeMerkleTree,
    DfaTable, Digest, MerkleHasher, PrivateCertError,
};

const P1_LEAF_PREFIX: u8 = 0x11;
const P1_LEAF_NAME: &[u8] = b"MINIDREGG/TOWER256/ALGCERT/P1LEAF/V1";
const P3_LEAF_PREFIX: u8 = 0x12;
const P3_LEAF_NAME: &[u8] = b"MINIDREGG/TOWER256/ALGCERT/P3LEAF/V1";
const CHAL1_PREFIX: u8 = 0x13;
const CHAL1_NAME: &[u8] = b"MINIDREGG/TOWER256/ALGCERT/CHAL1/V1";
const CHAL2_PREFIX: u8 = 0x14;
const CHAL2_NAME: &[u8] = b"MINIDREGG/TOWER256/ALGCERT/CHAL2/V1";
const CHAL3_PREFIX: u8 = 0x15;
const CHAL3_NAME: &[u8] = b"MINIDREGG/TOWER256/ALGCERT/CHAL3/V1";
const SCCHAL_PREFIX: u8 = 0x16;
const SCCHAL_NAME: &[u8] = b"MINIDREGG/TOWER256/ALGCERT/SCCHAL/V1";
const BATCH_PREFIX: u8 = 0x17;
const BATCH_NAME: &[u8] = b"MINIDREGG/TOWER256/ALGCERT/BATCH/V1";
const BFCHAL_PREFIX: u8 = 0x18;
const BFCHAL_NAME: &[u8] = b"MINIDREGG/TOWER256/ALGCERT/BFCHAL/V1";
