const CHALLENGE_CUSTOMIZATION: &[u8] = b"MD-FRI-C";
const QUERY_CUSTOMIZATION: &[u8] = b"MD-FRI-Q";

const ALG_RECEIPT_MAGIC: &[u8; 8] = b"MDACRT02";
const ALG_STMT_MAGIC: &[u8; 8] = b"MDASTM01";
const CSHAKE256_RATE: usize = 136;

/// Primitive generator `0x10005 = 65541` of `GF(2^32)^× ⊂ Tower256^×` (`orderOf = 2^32 - 1`).
pub const ZETA_U64: u64 = 65_541;
/// Exact multiplicative inverse `zeta^(2^32 - 2) = 848_205_651` in Fan–Paar `Coordinate 5`.
pub const ZETA_INV_U64: u64 = 848_205_651;

/// Exact `5 × 5` Vandermonde inverse matrix at `[0, 1, 2, 3, 4]` in Fan–Paar `GF(2^8)`.
const VANDERMONDE_INV_5: [[u64; 5]; 5] = [
    [1, 0, 0, 0, 0],
    [6, 15, 7, 13, 3],
    [0, 1, 2, 3, 0],
    [1, 1, 1, 1, 0],
    [6, 14, 4, 15, 3],
];

static ALG_KECCAK_F_CALLS: AtomicU64 = AtomicU64::new(0);

/// Reset both the shared Merkle `Keccak-f[1600]` counter and the algebraic transcript counter.
pub fn reset_alg_keccak_counter() {
    reset_base_keccak_counter();
    ALG_KECCAK_F_CALLS.store(0, Ordering::SeqCst);
}

/// Total SP 800-185 `cSHAKE256` `Keccak-f[1600]` permutations across Merkle + algebraic XOF calls.
pub fn alg_keccak_f_count() -> u64 {
    base_keccak_f_count() + ALG_KECCAK_F_CALLS.load(Ordering::SeqCst)
}

#[inline]
fn record_alg_cshake256_blocks(customization_len: usize, input_len: usize) {
    let cust_blocks = if customization_len == 0 {
        0
    } else {
        let hdr = 2 + if customization_len * 8 < 256 { 2 } else { 3 } + customization_len;
        hdr.div_ceil(CSHAKE256_RATE).max(1)
    };
    let msg_blocks = (input_len / CSHAKE256_RATE) + 1;
    ALG_KECCAK_F_CALLS.fetch_add((cust_blocks + msg_blocks) as u64, Ordering::Relaxed);
}

#[inline]
fn xof32_alg(customization: &[u8], input: &[u8]) -> Digest {
    record_alg_cshake256_blocks(customization.len(), input.len());
    cshake256_xof(customization, input, 32)
        .try_into()
        .expect("32-byte digest")
}

fn prefixed_cust(prefix: u8, name: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(1 + name.len());
    out.push(prefix);
    out.extend_from_slice(name);
    out
}

/// Unconditional unique-decoding (`UD-100`) FRI query count for `rate = 2^{-log_blowup}`:
/// smallest `q` with `((1 + 2^{-log_blowup}) / 2)^q <= 2^{-100}` (`q = 148` at `log_blowup = 2`).
pub const fn ud100_fri_queries(log_blowup: usize) -> usize {
    match log_blowup {
        0 => 4096,
        1 => 241,
        2 => 148,
        3 => 121,
        4 => 110,
        _ => 105,
    }
}

