/// Degree-`<= 4` univariate polynomial `c0 + c1*X + c2*X^2 + c3*X^3 + c4*X^4` over `Tower256`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PolyDeg4 {
    pub coeffs: [Tower256; 5],
}

impl PolyDeg4 {
    #[inline]
    pub fn eval(&self, x: Tower256) -> Tower256 {
        eval_horner(&self.coeffs, x)
    }

    #[inline]
    pub fn sum_bool(&self) -> Tower256 {
        self.eval(Tower256::ZERO).add(self.eval(Tower256::ONE))
    }

    pub fn encode_bytes(&self, out: &mut Vec<u8>) {
        for c in &self.coeffs {
            out.extend_from_slice(&c.to_le_bytes());
        }
    }
}

/// Degree-`<= 2` univariate polynomial `c0 + c1*X + c2*X^2` over `Tower256` for BaseFold rounds.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PolyDeg2 {
    pub coeffs: [Tower256; 3],
}

impl PolyDeg2 {
    #[inline]
    pub fn eval(&self, x: Tower256) -> Tower256 {
        eval_horner(&self.coeffs, x)
    }

    #[inline]
    pub fn sum_bool(&self) -> Tower256 {
        self.eval(Tower256::ZERO).add(self.eval(Tower256::ONE))
    }

    pub fn encode_bytes(&self, out: &mut Vec<u8>) {
        for c in &self.coeffs {
            out.extend_from_slice(&c.to_le_bytes());
        }
    }
}

