// ---------------------------------------------------------------------------------------------
// Field, Polynomial, Prefix-Power Digit-DP, & Coset Novel-Basis Helpers

#[inline]
pub fn zeta_c() -> Tower256 {
    leaf_of_u64(ZETA_U64)
}

#[inline]
pub fn zeta_inv_c() -> Tower256 {
    leaf_of_u64(ZETA_INV_U64)
}

/// Canonical disjoint coset offset `2^ell` (`cosetOffset ell` in Lean).
#[inline]
pub fn coset_offset(ell: usize) -> Tower256 {
    let mut limbs = [0u64; 4];
    limbs[ell / 64] = 1u64 << (ell % 64);
    Tower256::from_limbs(limbs)
}

#[inline]
pub fn alg_degree_schedule(cube_dim: usize, round: usize) -> usize {
    (1usize << (cube_dim + 1).saturating_sub(round)).max(1)
}

#[inline]
pub fn pow_tower256(mut base: Tower256, mut exp: u64) -> Tower256 {
    let mut acc = Tower256::ONE;
    while exp > 0 {
        if (exp & 1) == 1 {
            acc = acc.mul(base);
        }
        base = base.square();
        exp >>= 1;
    }
    acc
}

#[inline]
pub fn eval_horner(cs: &[Tower256], x: Tower256) -> Tower256 {
    cs.iter()
        .rev()
        .fold(Tower256::ZERO, |acc, &c| c.add(x.mul(acc)))
}

/// Montgomery batch inversion over `Tower256` (one inverse and `3 * n` products).
pub fn batch_inverse256(xs: &[Tower256]) -> Result<Vec<Tower256>, PrivateCertError> {
    if xs.is_empty() {
        return Ok(Vec::new());
    }
    let mut pref = Vec::with_capacity(xs.len());
    let mut acc = Tower256::ONE;
    for &x in xs {
        pref.push(acc);
        acc = acc.mul(x);
    }
    let mut inv_acc = acc.inverse().map_err(|_| PrivateCertError::SingularInterpolation)?;
    let mut out = vec![Tower256::ZERO; xs.len()];
    for i in (0..xs.len()).rev() {
        out[i] = pref[i].mul(inv_acc);
        inv_acc = inv_acc.mul(xs[i]);
    }
    Ok(out)
}

/// In-place Boolean Möbius transform over `{0, 1}^m_vars` (`O(m_vars * 2^m_vars)` XORs).
pub fn mobius_in_place(m_vars: usize, table: &mut [Tower256]) {
    let total = 1usize << m_vars;
    debug_assert_eq!(table.len(), total);
    for bit in 0..m_vars {
        let step = 1usize << bit;
        let block = step << 1;
        for base in (0..total).step_by(block) {
            for off in 0..step {
                let lo = table[base + off];
                table[base + step + off] = table[base + step + off].add(lo);
            }
        }
    }
}

#[inline]
fn apply_pivots(pivots: &[Tower256], x: Tower256) -> Tower256 {
    pivots
        .iter()
        .fold(x, |y, &p| y.square().add(p.mul(y)))
}

#[inline]
fn raw_domain_point(beta: &[Tower256], offset: Tower256, k: usize, index: usize) -> Tower256 {
    (0..k)
        .filter(|&i| (index >> i) & 1 == 1)
        .fold(offset, |acc, i| acc.add(beta[i]))
}

#[inline]
fn dom_point(
    beta: &[Tower256],
    offset: Tower256,
    ell: usize,
    round: usize,
    pivots: &[Tower256],
    index: usize,
) -> Tower256 {
    apply_pivots(pivots, raw_domain_point(beta, offset, ell - round, index))
}

fn tabulate_subspace_domain(
    beta: &[Tower256],
    offset: Tower256,
    bits: usize,
    pivots: &[Tower256],
) -> Vec<Tower256> {
    let size = 1usize << bits;
    let mut dom = Vec::with_capacity(size);
    dom.push(apply_pivots(pivots, offset));
    for b in 0..bits {
        let img = apply_pivots(pivots, beta[b]);
        let cur_len = dom.len();
        for idx in 0..cur_len {
            dom.push(dom[idx].add(img));
        }
    }
    dom
}

/// Compute the first `m_vars` additive pivots (`pivotC (unitBasis ell) r` in Lean) and their inverses.
pub fn compute_pivots_and_inverses(
    ell: usize,
    m_vars: usize,
) -> Result<(Vec<Tower256>, Vec<Tower256>), PrivateCertError> {
    let beta = unit_basis(ell);
    let mut pivs = Vec::with_capacity(m_vars);
    for r in 0..m_vars {
        let p = apply_pivots(&pivs, beta[ell - 1 - r]);
        if p.is_zero() {
            return Err(PrivateCertError::ZeroPivot(r));
        }
        pivs.push(p);
    }
    let piv_invs = batch_inverse256(&pivs)?;
    Ok((pivs, piv_invs))
}

/// Precompute per-round normalized coset coordinates `thetas[s][k] = dom_s[k] * piv_invs[s]`
/// (`0 <= s < m_vars`, `0 <= k < 2^(ell - s - 1)`) once across all 17 encoded columns.
fn precompute_coset_thetas(
    ell: usize,
    m_vars: usize,
    pivs: &[Tower256],
    piv_invs: &[Tower256],
) -> Vec<Vec<Tower256>> {
    let beta = unit_basis(ell);
    let offset = coset_offset(ell);
    (0..m_vars)
        .map(|s| {
            let dom_lo = tabulate_subspace_domain(&beta, offset, ell - s - 1, &pivs[..s]);
            let pinv = piv_invs[s];
            dom_lo.into_iter().map(|d| d.mul(pinv)).collect()
        })
        .collect()
}

/// Zero-inner-allocation flat `O(m_vars * 2^(ell - 1))` coset novel-basis encoder using precomputed `thetas`.
fn coset_from_coeffs_with_thetas(
    ell: usize,
    m_vars: usize,
    thetas_by_step: &[Vec<Tower256>],
    coeffs: &[Tower256],
) -> Vec<Tower256> {
    let coset_len = 1usize << ell;
    let base_tail = 1usize << (ell - m_vars);
    let mut buf = Vec::with_capacity(coset_len);
    for &c in coeffs.iter().take(1usize << m_vars) {
        buf.resize(buf.len() + base_tail, c);
    }
    let mut scratch = vec![Tower256::ZERO; coset_len];
    for s in (0..m_vars).rev() {
        let half = 1usize << (ell - s - 1);
        let next_groups = 1usize << s;
        let thetas = &thetas_by_step[s];
        let mid = next_groups * half;
        for u in 0..next_groups {
            let ev_off = u * half;
            let od_off = mid + u * half;
            let dst_off = u * (2 * half);
            for k in 0..half {
                let ev = buf[ev_off + k];
                let od = buf[od_off + k];
                let lo_val = ev.add(thetas[k].mul(od));
                scratch[dst_off + k] = lo_val;
                scratch[dst_off + k + half] = lo_val.add(od);
            }
        }
        std::mem::swap(&mut buf, &mut scratch);
    }
    buf
}

fn coset_encode_table_with_thetas(
    ell: usize,
    m_vars: usize,
    thetas_by_step: &[Vec<Tower256>],
    table: &[Tower256],
) -> Vec<Tower256> {
    let mut coeffs = table.to_vec();
    mobius_in_place(m_vars, &mut coeffs);
    coset_from_coeffs_with_thetas(ell, m_vars, thetas_by_step, &coeffs)
}

/// Fast `O(m_vars * 2^(ell - 1))` coset novel-basis encoder from Möbius coefficients `coeffs`
/// (`cosetFromCoeffsF` / `cosetEncodeTableC` in Lean).
pub fn coset_from_coeffs(
    ell: usize,
    m_vars: usize,
    pivs: &[Tower256],
    piv_invs: &[Tower256],
    coeffs: &[Tower256],
) -> Vec<Tower256> {
    let thetas = precompute_coset_thetas(ell, m_vars, pivs, piv_invs);
    coset_from_coeffs_with_thetas(ell, m_vars, &thetas, coeffs)
}

/// Encode a `(d + 1)`-variable hypercube table on `coset_offset(ell) + V_ell`.
pub fn coset_encode_table(
    ell: usize,
    m_vars: usize,
    pivs: &[Tower256],
    piv_invs: &[Tower256],
    table: &[Tower256],
) -> Vec<Tower256> {
    let thetas = precompute_coset_thetas(ell, m_vars, pivs, piv_invs);
    coset_encode_table_with_thetas(ell, m_vars, &thetas, table)
}

/// Compute `maskedContentCommit(fri_ell, cube_dim, word, content_mask)` matching Lean byte-for-byte.
pub fn masked_content_commit(
    fri_ell: usize,
    cube_dim: usize,
    word: &[u8],
    content_mask: &[Tower256],
) -> Result<Digest, PrivateCertError> {
    let n_half = 1usize << cube_dim;
    if word.len() > n_half || content_mask.len() != n_half || cube_dim + 1 > fri_ell || fri_ell > 24
    {
        return Err(PrivateCertError::InvalidShape(
            "masked_content_commit shape mismatch",
        ));
    }
    let (pivs, piv_invs) = compute_pivots_and_inverses(fri_ell, cube_dim + 1)?;
    let mut col0 = vec![Tower256::ZERO; 2 * n_half];
    for (i, &b) in word.iter().enumerate() {
        col0[i] = leaf_of_u64(u64::from(b));
    }
    col0[n_half..2 * n_half].copy_from_slice(content_mask);
    let coset0 = coset_encode_table(fri_ell, cube_dim + 1, &pivs, &piv_invs, &col0);
    let hasher = MerkleHasher::new();
    Ok(hasher.build_tree(&coset0, fri_ell).root())
}

/// Interpolate a degree-`<= 4` polynomial from evaluations at `[0, 1, 2, 3, 4]`.
pub fn interpolate_deg4(evals5: &[Tower256; 5]) -> PolyDeg4 {
    let mut coeffs = [Tower256::ZERO; 5];
    for i in 0..5 {
        let mut acc = Tower256::ZERO;
        for j in 0..5 {
            let c = VANDERMONDE_INV_5[i][j];
            if c != 0 {
                acc = acc.add(leaf_of_u64(c).mul(evals5[j]));
            }
        }
        coeffs[i] = acc;
    }
    PolyDeg4 { coeffs }
}

/// `O(d)` Digit-DP Prefix-Power MLE (`prefixPowerMleC` in Lean): evaluates `sum_{i < k} tau^i * chi_i(r)`.
pub fn prefix_power_mle(d: usize, k: usize, tau: Tower256, r: &[Tower256]) -> Tower256 {
    let mut pows = Vec::with_capacity(d);
    let mut cur = tau;
    for _ in 0..d {
        pows.push(cur);
        cur = cur.square();
    }
    fn full_cube(m: usize, pows: &[Tower256], r: &[Tower256]) -> Tower256 {
        let mut acc = Tower256::ONE;
        for j in 0..m {
            let rj = r[j];
            let term = Tower256::ONE.add(rj).add(rj.mul(pows[j]));
            acc = acc.mul(term);
        }
        acc
    }
    fn aux(m: usize, k: usize, pows: &[Tower256], r: &[Tower256]) -> Tower256 {
        if k == 0 {
            return Tower256::ZERO;
        }
        if m == 0 {
            return Tower256::ONE;
        }
        let m1 = m - 1;
        let half = 1usize << m1;
        if k >= 2 * half {
            return full_cube(m, pows, r);
        }
        let rm = r[m1];
        let one_plus_rm = Tower256::ONE.add(rm);
        if k <= half {
            one_plus_rm.mul(aux(m1, k, pows, r))
        } else {
            let lo = one_plus_rm.mul(full_cube(m1, pows, r));
            let hi = rm.mul(pows[m1]).mul(aux(m1, k - half, pows, r));
            lo.add(hi)
        }
    }
    aux(d, k, &pows, r)
}

#[inline]
fn chi_at_nat(d: usize, idx: usize, r: &[Tower256]) -> Tower256 {
    let mut acc = Tower256::ONE;
    for (j, &rj) in r.iter().enumerate().take(d) {
        let factor = if (idx >> j) & 1 == 1 {
            rj
        } else {
            Tower256::ONE.add(rj)
        };
        acc = acc.mul(factor);
    }
    acc
}

fn tabulate_chi(d: usize, r: &[Tower256]) -> Vec<Tower256> {
    let mut dp = vec![Tower256::ONE];
    for &rj in r.iter().take(d) {
        let r0 = Tower256::ONE.add(rj);
        let prev = dp;
        let n = prev.len();
        let mut next = Vec::with_capacity(2 * n);
        for &v in &prev {
            next.push(v.mul(r0));
        }
        for &v in &prev {
            next.push(v.mul(rj));
        }
        dp = next;
    }
    dp
}

// ---------------------------------------------------------------------------------------------
// Framing, Customizations, Midstate Vector-LeafHasher, & Transcript Derivation

#[inline]
fn encode_length(out: &mut Vec<u8>, n: usize) {
    out.resize(out.len() + n, 0);
    out.push(1);
}

#[inline]
fn envelope(out: &mut Vec<u8>, payload: &[u8]) {
    encode_length(out, payload.len());
    out.extend_from_slice(payload);
}

#[inline]
fn nat_coord_bytes(n: u64) -> [u8; 32] {
    leaf_of_u64(n).to_le_bytes()
}

fn claim_bytes(claim: ClaimData) -> Vec<u8> {
    let mut out = Vec::new();
    match claim {
        ClaimData::Accept(b) => {
            out.push(0);
            out.push(if b { 1 } else { 0 });
        }
        ClaimData::Count(n) => {
            out.push(1);
            out.extend_from_slice(&nat_coord_bytes(n));
        }
        ClaimData::Bound { lo, hi } => {
            out.push(2);
            out.extend_from_slice(&nat_coord_bytes(lo));
            out.extend_from_slice(&nat_coord_bytes(hi));
        }
    }
    out
}

pub fn alg_base_stmt_bytes(stmt: &AlgebraicContentCert) -> Vec<u8> {
    let mut out = Vec::with_capacity(512);
    envelope(&mut out, &stmt.content_root);
    envelope(&mut out, &nat_coord_bytes(stmt.record_length as u64));
    envelope(&mut out, &stmt.automaton_root);
    envelope(&mut out, &claim_bytes(stmt.claim));
    envelope(&mut out, &nat_coord_bytes(stmt.cube_dim as u64));
    envelope(&mut out, &nat_coord_bytes(stmt.fri_ell as u64));
    envelope(&mut out, &nat_coord_bytes(stmt.fri_queries as u64));
    out
}

fn derive_chal_at(cust: &[u8], prefix_bytes: &[u8], idx: u64) -> Tower256 {
    let mut inp = Vec::with_capacity(prefix_bytes.len() + 66);
    inp.extend_from_slice(prefix_bytes);
    envelope(&mut inp, &nat_coord_bytes(idx));
    Tower256::from_le_bytes(xof32_alg(cust, &inp))
}

fn alg_round1_transcript(stmt: &AlgebraicContentCert, phase1_root: &Digest) -> Vec<u8> {
    let base = alg_base_stmt_bytes(stmt);
    let mut out = Vec::with_capacity(base.len() + 140);
    envelope(&mut out, &base);
    envelope(&mut out, phase1_root);
    out
}

fn alg_round2_transcript(r1_bytes: &[u8], mult_root: &Digest) -> Vec<u8> {
    let mut out = Vec::with_capacity(r1_bytes.len() + 70);
    out.extend_from_slice(r1_bytes);
    envelope(&mut out, mult_root);
    out
}

fn alg_round3_transcript(r2_bytes: &[u8], phase3_root: &Digest) -> Vec<u8> {
    let mut out = Vec::with_capacity(r2_bytes.len() + 70);
    out.extend_from_slice(r2_bytes);
    envelope(&mut out, phase3_root);
    out
}

fn alg_batch_transcript(
    r3_bytes: &[u8],
    sc_polys: &[PolyDeg4],
    col_evals: &[Tower256; 17],
) -> Vec<u8> {
    let mut polys_buf = Vec::with_capacity(sc_polys.len() * 160);
    for p in sc_polys {
        p.encode_bytes(&mut polys_buf);
    }
    let mut evals_buf = Vec::with_capacity(17 * 32);
    for y in col_evals {
        evals_buf.extend_from_slice(&y.to_le_bytes());
    }
    let mut out = Vec::new();
    out.extend_from_slice(r3_bytes);
    envelope(&mut out, &polys_buf);
    envelope(&mut out, &evals_buf);
    out
}

#[inline]
fn eq_point(m: usize, r: &[Tower256], s: &[Tower256]) -> Tower256 {
    let mut acc = Tower256::ONE;
    for k in 0..m {
        acc = acc.mul(Tower256::ONE.add(r[k]).add(s[k]));
    }
    acc
}

fn build_basefold_transcript(
    d: usize,
    batch_bytes: &[u8],
    bf_polys: &[PolyDeg2],
    eval_fold_roots: &[Digest],
    bf_final_coeff: Tower256,
) -> (Vec<Tower256>, Vec<u8>) {
    let bf_chal_cust = prefixed_cust(BFCHAL_PREFIX, BFCHAL_NAME);
    let mut s_acc = Vec::with_capacity(d + 1);
    let mut tr = batch_bytes.to_vec();
    let mut q_buf = Vec::with_capacity(96);
    for j in 0..=d {
        envelope(&mut tr, &nat_coord_bytes(j as u64));
        q_buf.clear();
        bf_polys[j].encode_bytes(&mut q_buf);
        envelope(&mut tr, &q_buf);
        let sj = Tower256::from_le_bytes(xof32_alg(&bf_chal_cust, &tr));
        s_acc.push(sj);
        if j < d {
            envelope(&mut tr, &eval_fold_roots[j]);
        }
    }
    envelope(&mut tr, &bf_final_coeff.to_le_bytes());
    (s_acc, tr)
}

fn run_basefold_verifier(
    d: usize,
    batch_bytes: &[u8],
    r_full: &[Tower256],
    bf_polys: &[PolyDeg2],
    eval_fold_roots: &[Digest],
    bf_final_coeff: Tower256,
    init_claim: Tower256,
) -> Result<(Vec<Tower256>, Vec<u8>), PrivateCertError> {
    if bf_polys.len() != d + 1 || eval_fold_roots.len() != d {
        return Err(PrivateCertError::VerificationFailed(
            "basefold array length mismatch",
        ));
    }
    let bf_chal_cust = prefixed_cust(BFCHAL_PREFIX, BFCHAL_NAME);
    let mut claim = init_claim;
    let mut s_acc = Vec::with_capacity(d + 1);
    let mut tr = batch_bytes.to_vec();
    let mut q_buf = Vec::with_capacity(96);
    for j in 0..=d {
        let q = &bf_polys[j];
        if q.sum_bool() != claim {
            return Err(PrivateCertError::VerificationFailed(
                "basefold round q(0) + q(1) != claim",
            ));
        }
        envelope(&mut tr, &nat_coord_bytes(j as u64));
        q_buf.clear();
        q.encode_bytes(&mut q_buf);
        envelope(&mut tr, &q_buf);
        let sj = Tower256::from_le_bytes(xof32_alg(&bf_chal_cust, &tr));
        if sj == Tower256::ONE.add(r_full[j]) {
            return Err(PrivateCertError::VerificationFailed(
                "basefold degenerate s_j == 1 + r_j",
            ));
        }
        s_acc.push(sj);
        claim = q.eval(sj);
        if j < d {
            envelope(&mut tr, &eval_fold_roots[j]);
        }
    }
    if claim != eq_point(d + 1, r_full, &s_acc).mul(bf_final_coeff) {
        return Err(PrivateCertError::VerificationFailed(
            "basefold terminal claim != eq(rFull, sBF) * bfFinalCoeff",
        ));
    }
    envelope(&mut tr, &bf_final_coeff.to_le_bytes());
    Ok((s_acc, tr))
}

struct VecLeafHasher {
    cust_len: usize,
    core: CShake256Core,
}

impl VecLeafHasher {
    fn new(prefix: u8, name: &[u8]) -> Self {
        let cust = prefixed_cust(prefix, name);
        Self {
            cust_len: cust.len(),
            core: CShake256Core::new(&cust),
        }
    }

    #[inline]
    fn hash_cols(&self, cols: &[Tower256]) -> Tower256 {
        let byte_len = cols.len() * 32;
        record_alg_cshake256_blocks(self.cust_len, byte_len);
        let mut h = CShake256::from_core(self.core.clone());
        for c in cols {
            h.update(&c.to_le_bytes());
        }
        let mut out = [0u8; 32];
        h.finalize_xof().read(&mut out);
        Tower256::from_le_bytes(out)
    }
}

/// Deterministic seed expansion matching Lean's `FastProver.expandSeedC8` byte-for-byte.
pub fn expand_lean_seed_c8(cust_str: &str, seed: u64, count: usize) -> Vec<Tower256> {
    let cust = prefixed_cust(SEED_EXPAND_PREFIX, cust_str.as_bytes());
    let core = CShake256Core::new(&cust);
    let seed_bytes = nat_coord_bytes(seed);
    let mut out = Vec::with_capacity(count);
    for i in 0..count {
        let mut inp = [0u8; 64];
        inp[..32].copy_from_slice(&seed_bytes);
        inp[32..64].copy_from_slice(&nat_coord_bytes(i as u64));
        let mut h = CShake256::from_core(core.clone());
        h.update(&inp);
        let mut d = [0u8; 32];
        h.finalize_xof().read(&mut d);
        out.push(Tower256::from_le_bytes(d));
    }
    out
}

/// Production 256-bit CSPRNG expansion from a 32-byte `Digest` seed (independent of witness).
pub fn expand_digest_seed_c8(cust_str: &str, seed: &Digest, count: usize) -> Vec<Tower256> {
    let cust = prefixed_cust(SEED_EXPAND_PREFIX, cust_str.as_bytes());
    let core = CShake256Core::new(&cust);
    let mut out = Vec::with_capacity(count);
    for i in 0..count {
        let mut inp = [0u8; 40];
        inp[..32].copy_from_slice(seed);
        inp[32..40].copy_from_slice(&(i as u64).to_le_bytes());
        let mut h = CShake256::from_core(core.clone());
        h.update(&inp);
        let mut d = [0u8; 32];
        h.finalize_xof().read(&mut d);
        out.push(Tower256::from_le_bytes(d));
    }
    out
}

// ---------------------------------------------------------------------------------------------
// Unified Batched Pointwise Evaluator (`evalCombinedPhiC` & `evalTerminalPhiC`)

#[allow(clippy::too_many_arguments)]
#[inline]
fn eval_combined_phi(
    claim: ClaimData,
    record_length: usize,
    cube_dim: usize,
    init_f: Tower256,
    zeta: Tower256,
    zeta_inv: Tower256,
    alpha: Tower256,
    gamma: Tower256,
    beta: Tower256,
    rho_lin: Tower256,
    xd_val: Tower256,
    zeta_dp1: Tower256,
    p_lin_z: Tower256,
    z2_val: Tower256,
    z3_val: Tower256,
    ps: &[Tower256; 18],
    ys: &[Tower256; 16],
) -> Tower256 {
    let one = Tower256::ONE;
    let zero = Tower256::ZERO;
    let (y_b, y_s, y_nx, y_h, y_c) = (ys[0], ys[1], ys[2], ys[3], ys[4]);
    let (y_a1, y_d1, y_a2, y_d2) = (ys[5], ys[6], ys[7], ys[8]);
    let (y_m, y_hinv, y_ginv) = (ys[9], ys[10], ys[11]);
    let (y_mlin, y_u1, y_u2, y_u3) = (ys[12], ys[13], ys[14], ys[15]);

    let alpha2 = alpha.square();
    let alpha3 = alpha2.mul(alpha);
    let e_tup = y_b
        .add(alpha.mul(y_s))
        .add(alpha2.mul(y_nx))
        .add(alpha3.mul(y_h));
    let z_plus_1 = one.add(zeta);
    let c_step = one.add(z_plus_1.mul(y_h));

    let chi0 = ps[0];
    let chi_last = ps[1];
    let chi_d = ps[2];
    let p_lt_s = ps[3];
    let p_lm1_s = ps[4];
    let p_lt_c = ps[5];
    let p_lm1_c = ps[6];
    let p_lt_d = ps[7];
    let p_tab_gamma_d = ps[8];
    let p_tab_d = ps[9];
    let p_lt_theta = ps[10];
    let p_tab_one = ps[11];
    let p_bit_d = ps[12];
    let p_bit_c = ps[13];
    let p_bit_prev_c = ps[14];
    let p_step1 = ps[15];
    let p_step2 = ps[16];

    let e0 = chi0.mul(init_f)
        .add(p_lt_s.mul(y_s))
        .add(p_lm1_s.mul(y_nx));
    let e1 = chi0
        .add(p_lt_c.mul(y_c))
        .add(p_lm1_c.mul(y_c).mul(c_step));
    let e2 = p_lt_d.mul(y_hinv.mul(gamma.add(e_tup)).add(one));
    let e3 = p_tab_gamma_d.mul(y_ginv).add(p_tab_d);
    let e4 = p_lt_theta.mul(y_hinv).add(p_tab_one.mul(y_m).mul(y_ginv));

    let (e5, e6, e7, e8, e9, e10) = match claim {
        ClaimData::Accept(acc_b) => {
            let acc_f = if acc_b { one } else { zero };
            (chi_last.mul(y_h.add(acc_f)), zero, zero, zero, zero, zero)
        }
        ClaimData::Count(n) => {
            let zn = pow_tower256(zeta, n);
            (
                chi_last.mul(y_c.mul(c_step).add(zn)),
                zero,
                zero,
                zero,
                zero,
                zero,
            )
        }
        ClaimData::Bound { lo, hi } => {
            let hi_cap = hi.min(record_length as u64);
            let z_lo = pow_tower256(zeta, lo);
            let z_hi = pow_tower256(zeta, hi_cap);
            let two_pow_d = 1u64 << cube_dim;
            let z_last1 = one.add(pow_tower256(zeta, two_pow_d));
            let z_last2 = one.add(pow_tower256(zeta_inv, two_pow_d));
            let c5 = p_bit_d.mul(y_d1.square().add(y_d1));
            let c6 = p_bit_d.mul(y_d2.square().add(y_d2));
            let c7 = chi0.mul(z_lo)
                .add(p_bit_c.mul(y_a1))
                .add(p_bit_prev_c.mul(y_a1))
                .add(p_step1.mul(y_a1).mul(y_d1));
            let c8 = chi0.mul(z_hi)
                .add(p_bit_c.mul(y_a2))
                .add(p_bit_prev_c.mul(y_a2))
                .add(p_step2.mul(y_a2).mul(y_d2));
            let c_end = chi_last.mul(y_c).mul(c_step);
            let c9 = c_end.add(chi_d.mul(y_a1).mul(one.add(z_last1.mul(y_d1))));
            let c10 = c_end.add(chi_d.mul(y_a2).mul(one.add(z_last2.mul(y_d2))));
            (c5, c6, c7, c8, c9, c10)
        }
    };

    let eqs = [e0, e1, e2, e3, e4, e5, e6, e7, e8, e9, e10];
    let wit_batch = eval_horner(&eqs, beta);
    let wit_term = one.add(xd_val).mul(wit_batch);
    let p1_full = p_lin_z.add(zeta_dp1.mul(xd_val));
    let mask_body = y_mlin
        .add(p1_full.mul(y_u1))
        .add(z2_val.mul(y_u2))
        .add(z3_val.mul(y_u3));
    wit_term.add(rho_lin.mul(mask_body))
}

#[allow(clippy::too_many_arguments)]
fn eval_terminal_phi(
    stmt: &AlgebraicContentCert,
    dfa: &DfaTable,
    alpha: Tower256,
    theta: Tower256,
    gamma: Tower256,
    beta: Tower256,
    tau_s: Tower256,
    tau_c: Tower256,
    tau_d: Tower256,
    rho_lin: Tower256,
    r_full: &[Tower256],
    ys: &[Tower256; 16],
) -> Tower256 {
    let d = stmt.cube_dim;
    let l = stmt.record_length;
    let m_tab = dfa.states * 256;
    let r_cube = &r_full[..d];
    let xd_val = r_full[d];
    let zeta = zeta_c();
    let zeta_inv = zeta_inv_c();
    let one = Tower256::ONE;
    let zero = Tower256::ZERO;

    let mut z_pow = zeta;
    let mut p_lin_z = zero;
    let mut z2_val = zero;
    let mut z3_val = zero;
    for &rk in r_cube {
        let rk2 = rk.square();
        let rk3 = rk2.mul(rk);
        p_lin_z = p_lin_z.add(z_pow.mul(rk));
        z2_val = z2_val.add(z_pow.mul(rk2.add(rk)));
        z3_val = z3_val.add(z_pow.mul(rk3.add(rk2)));
        z_pow = z_pow.mul(zeta);
    }
    let zeta_dp1 = z_pow;
    let rd2 = xd_val.square();
    let rd3 = rd2.mul(xd_val);
    z2_val = z2_val.add(zeta_dp1.mul(rd2.add(xd_val)));
    z3_val = z3_val.add(zeta_dp1.mul(rd3.add(rd2)));

    let chi0 = chi_at_nat(d, 0, r_cube);
    let chi_last = chi_at_nat(d, l.saturating_sub(1), r_cube);
    let chi_d = chi_at_nat(d, d, r_cube);
    let p_lt_s = prefix_power_mle(d, l, tau_s, r_cube);
    let p_lm1_s = tau_s.mul(prefix_power_mle(d, l.saturating_sub(1), tau_s, r_cube));
    let p_lt_c = prefix_power_mle(d, l, tau_c, r_cube);
    let p_lm1_c = tau_c.mul(prefix_power_mle(d, l.saturating_sub(1), tau_c, r_cube));
    let p_lt_d = prefix_power_mle(d, l, tau_d, r_cube);
    let p_tab_d = prefix_power_mle(d, m_tab, tau_d, r_cube);
    let p_lt_theta = prefix_power_mle(d, l, theta, r_cube);
    let p_tab_one = prefix_power_mle(d, m_tab, one, r_cube);

    let chi_arr = tabulate_chi(d, r_cube);
    let alpha2 = alpha.square();
    let alpha3 = alpha2.mul(alpha);
    let mut p_tab_gamma_d = zero;
    let mut td_pow = one;
    for k in 0..m_tab {
        let s = (k / 256) as u64;
        let b = (k % 256) as u64;
        let nx = dfa.delta[k];
        let hit = u64::from(dfa.accepting[nx]);
        let tk = leaf_of_u64(b)
            .add(alpha.mul(leaf_of_u64(s)))
            .add(alpha2.mul(leaf_of_u64(nx as u64)))
            .add(alpha3.mul(leaf_of_u64(hit)));
        let w = td_pow.mul(gamma.add(tk)).mul(chi_arr[k]);
        p_tab_gamma_d = p_tab_gamma_d.add(w);
        td_pow = td_pow.mul(tau_d);
    }

    let (p_bit_d, p_bit_c, p_bit_prev_c, p_step1, p_step2) = match stmt.claim {
        ClaimData::Bound { .. } => {
            let b_d = prefix_power_mle(d, d + 1, tau_d, r_cube);
            let b_c = prefix_power_mle(d, d + 1, tau_c, r_cube);
            let b_prev = tau_c.mul(prefix_power_mle(d, d, tau_c, r_cube));
            let mut acc1 = zero;
            let mut acc2 = zero;
            let mut tc_pow = tau_c;
            let mut z1 = zeta;
            let mut z2 = zeta_inv;
            for &ck in chi_arr.iter().take(d) {
                acc1 = acc1.add(tc_pow.mul(one.add(z1)).mul(ck));
                acc2 = acc2.add(tc_pow.mul(one.add(z2)).mul(ck));
                tc_pow = tc_pow.mul(tau_c);
                z1 = z1.square();
                z2 = z2.square();
            }
            (b_d, b_c, b_prev, acc1, acc2)
        }
        _ => (zero, zero, zero, zero, zero),
    };

    let ps = [
        chi0,
        chi_last,
        chi_d,
        p_lt_s,
        p_lm1_s,
        p_lt_c,
        p_lm1_c,
        p_lt_d,
        p_tab_gamma_d,
        p_tab_d,
        p_lt_theta,
        p_tab_one,
        p_bit_d,
        p_bit_c,
        p_bit_prev_c,
        p_step1,
        p_step2,
        p_lin_z,
    ];
    eval_combined_phi(
        stmt.claim,
        l,
        d,
        leaf_of_u64(dfa.initial as u64),
        zeta,
        zeta_inv,
        alpha,
        gamma,
        beta,
        rho_lin,
        xd_val,
        zeta_dp1,
        p_lin_z,
        z2_val,
        z3_val,
        &ps,
        ys,
    )
}

// ---------------------------------------------------------------------------------------------
// StreamCodec Wire Helpers + Coset Additive-FRI Prover & Verifier (`offset = coset_offset(ell)`)

fn encode_nat_255(out: &mut Vec<u8>, mut value: u128) {
    while value > 0 {
        out.push((value % 255) as u8);
        value /= 255;
    }
    out.push(255);
}

fn encode_digest_stream(out: &mut Vec<u8>, bytes: &Digest) {
    let mut limbs: Vec<u32> = bytes
        .chunks_exact(4)
        .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    loop {
        while limbs.last() == Some(&0) {
            limbs.pop();
        }
        if limbs.is_empty() {
            break;
        }
        let mut rem: u64 = 0;
        for limb in limbs.iter_mut().rev() {
            let cur = (rem << 32) | u64::from(*limb);
            *limb = (cur / 255) as u32;
            rem = cur % 255;
        }
        out.push(rem as u8);
    }
    out.push(255);
}

struct StreamReader<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> StreamReader<'a> {
    fn byte(&mut self) -> Result<u8, PrivateCertError> {
        let b = *self
            .bytes
            .get(self.pos)
            .ok_or(PrivateCertError::MalformedWire("truncated"))?;
        self.pos += 1;
        Ok(b)
    }

    fn take(&mut self, n: usize) -> Result<&'a [u8], PrivateCertError> {
        let end = self
            .pos
            .checked_add(n)
            .ok_or(PrivateCertError::MalformedWire("length overflow"))?;
        let s = self
            .bytes
            .get(self.pos..end)
            .ok_or(PrivateCertError::MalformedWire("truncated slice"))?;
        self.pos = end;
        Ok(s)
    }

    fn nat_usize(&mut self) -> Result<usize, PrivateCertError> {
        let mut digits = Vec::new();
        loop {
            let b = self.byte()?;
            if b == 255 {
                break;
            }
            digits.push(b);
        }
        if digits.last() == Some(&0) {
            return Err(PrivateCertError::MalformedWire("non-canonical base-255 nat"));
        }
        let mut val: usize = 0;
        for &d in digits.iter().rev() {
            val = val
                .checked_mul(255)
                .and_then(|v| v.checked_add(usize::from(d)))
                .ok_or(PrivateCertError::MalformedWire("nat overflow"))?;
        }
        Ok(val)
    }

    fn digest_stream(&mut self) -> Result<Digest, PrivateCertError> {
        let mut digits = Vec::new();
        loop {
            let b = self.byte()?;
            if b == 255 {
                break;
            }
            digits.push(b);
        }
        if digits.last() == Some(&0) {
            return Err(PrivateCertError::MalformedWire("non-canonical digest nat"));
        }
        let mut limbs = [0u32; 8];
        for &d in digits.iter().rev() {
            let mut carry = u64::from(d);
            for limb in &mut limbs {
                let cur = u64::from(*limb) * 255 + carry;
                *limb = cur as u32;
                carry = cur >> 32;
            }
            if carry != 0 {
                return Err(PrivateCertError::MalformedWire("digest >= 2^256"));
            }
        }
        let mut out = [0u8; 32];
        for (chunk, &limb) in out.chunks_exact_mut(4).zip(limbs.iter()) {
            chunk.copy_from_slice(&limb.to_le_bytes());
        }
        Ok(out)
    }

    fn c8(&mut self) -> Result<Tower256, PrivateCertError> {
        let s = self.take(32)?;
        Ok(Tower256::from_le_bytes(s.try_into().expect("32B")))
    }

    fn merkle_path_stream(&mut self) -> Result<Vec<Digest>, PrivateCertError> {
        let n = self.nat_usize()?;
        if n > 256 {
            return Err(PrivateCertError::MalformedWire("merkle path too deep"));
        }
        (0..n).map(|_| self.digest_stream()).collect()
    }
}

#[derive(Clone, Debug)]
struct DecodedFriReceipt {
    roots: Vec<Digest>,
    challenges: Vec<Tower256>,
    query_seeds: Vec<usize>,
    openings: Vec<Vec<CosetPairOpening>>,
    final_coeffs: Vec<Tower256>,
}

fn decode_fri_receipt(
    bytes: &[u8],
    ell: usize,
    m: usize,
    query_count: usize,
) -> Result<DecodedFriReceipt, PrivateCertError> {
    let mut r = StreamReader { bytes, pos: 0 };
    let n_roots = r.nat_usize()?;
    if n_roots != m + 1 {
        return Err(PrivateCertError::MalformedWire("wrong FRI roots count"));
    }
    let roots = (0..n_roots)
        .map(|_| r.digest_stream())
        .collect::<Result<Vec<_>, _>>()?;
    let n_ch = r.nat_usize()?;
    if n_ch != m {
        return Err(PrivateCertError::MalformedWire("wrong FRI challenges count"));
    }
    let challenges = (0..m).map(|_| r.c8()).collect::<Result<Vec<_>, _>>()?;
    let n_seeds = r.nat_usize()?;
    if n_seeds != query_count {
        return Err(PrivateCertError::MalformedWire("wrong FRI seeds count"));
    }
    let seed_bound = 1usize << ell.saturating_sub(1);
    let mut query_seeds = Vec::with_capacity(query_count);
    for _ in 0..query_count {
        let s = r.nat_usize()?;
        if s >= seed_bound {
            return Err(PrivateCertError::MalformedWire("FRI seed out of bounds"));
        }
        query_seeds.push(s);
    }
    let n_rounds = r.nat_usize()?;
    if n_rounds != m {
        return Err(PrivateCertError::MalformedWire("wrong FRI opening rounds"));
    }
    let mut openings = Vec::with_capacity(m);
    for _ in 0..m {
        let n_q = r.nat_usize()?;
        if n_q != query_count {
            return Err(PrivateCertError::MalformedWire("wrong FRI round query count"));
        }
        let mut round_ops = Vec::with_capacity(query_count);
        for _ in 0..query_count {
            let left = r.c8()?;
            let right = r.c8()?;
            let pair_path = r.merkle_path_stream()?;
            round_ops.push(CosetPairOpening {
                left,
                right,
                pair_path,
            });
        }
        openings.push(round_ops);
    }
    let n_final = r.nat_usize()?;
    if n_final > (1usize << (ell - m)) {
        return Err(PrivateCertError::MalformedWire("too many final coeffs"));
    }
    let final_coeffs = (0..n_final).map(|_| r.c8()).collect::<Result<Vec<_>, _>>()?;
    if r.pos != bytes.len() {
        return Err(PrivateCertError::MalformedWire("trailing bytes in FRI receipt"));
    }
    Ok(DecodedFriReceipt {
        roots,
        challenges,
        query_seeds,
        openings,
        final_coeffs,
    })
}

fn basis_prefix_bytes(ell: usize, m: usize, beta: &[Tower256], offset: Tower256) -> Vec<u8> {
    let mut out = Vec::new();
    let mut tmp = Vec::new();
    encode_length(&mut tmp, ell);
    envelope(&mut out, &tmp);
    tmp.clear();
    encode_length(&mut tmp, m);
    envelope(&mut out, &tmp);
    envelope(&mut out, &offset.to_le_bytes());
    for (i, b) in beta.iter().enumerate() {
        let mut inner = Vec::new();
        tmp.clear();
        encode_length(&mut tmp, i);
        envelope(&mut inner, &tmp);
        envelope(&mut inner, &b.to_le_bytes());
        envelope(&mut out, &inner);
    }
    out
}

fn roots_transcript_bytes(head: &[u8], roots: &[Digest], upto: usize) -> Vec<u8> {
    let mut out = head.to_vec();
    let mut tmp = Vec::new();
    for (n, root) in roots.iter().enumerate().take(upto + 1) {
        tmp.clear();
        encode_length(&mut tmp, n);
        envelope(&mut out, &tmp);
        envelope(&mut out, root);
    }
    out
}

fn derive_query_seeds_midstate(prefix: &[u8], ell: usize, query_count: usize) -> Vec<usize> {
    let core = CShake256Core::new(QUERY_CUSTOMIZATION);
    let mut base_hasher = CShake256::from_core(core);
    base_hasher.update(prefix);
    // Account for 1 customization block + prefix absorption blocks once, plus 1 tail block per query.
    let prefix_blocks = 1 + (prefix.len() / CSHAKE256_RATE);
    ALG_KECCAK_F_CALLS.fetch_add((prefix_blocks + query_count) as u64, Ordering::Relaxed);

    let seed_bits = ell - 1;
    let mut out = Vec::with_capacity(query_count);
    let mut tmp = Vec::new();
    let mut tail = Vec::new();
    for a in 0..query_count {
        tmp.clear();
        tail.clear();
        encode_length(&mut tmp, a);
        envelope(&mut tail, &tmp);
        let mut h = base_hasher.clone();
        h.update(&tail);
        let mut d = [0u8; 32];
        h.finalize_xof().read(&mut d);
        let mut low = [0u8; 8];
        low.copy_from_slice(&d[..8]);
        let v = u64::from_le_bytes(low);
        let seed = if seed_bits >= 64 {
            v as usize
        } else {
            (v & ((1u64 << seed_bits) - 1)) as usize
        };
        out.push(seed);
    }
    out
}

struct CosetFriProveOutput {
    initial_root: Digest,
    seeds: Vec<usize>,
    receipt_bytes: Vec<u8>,
}

fn prove_coset_fri_degree1(
    hasher: &MerkleHasher,
    statement_bytes: &[u8],
    ell: usize,
    m: usize,
    query_count: usize,
    pivs: &[Tower256],
    piv_invs: &[Tower256],
    word0: Vec<Tower256>,
) -> CosetFriProveOutput {
    let beta = unit_basis(ell);
    let offset = coset_offset(ell);
    let mut head = Vec::new();
    envelope(&mut head, statement_bytes);
    envelope(&mut head, &basis_prefix_bytes(ell, m, &beta, offset));

    let word0_tree = hasher.build_tree(&word0, ell);
    let root0 = word0_tree.root();

    let mut words: Vec<Vec<Tower256>> = Vec::with_capacity(m + 1);
    words.push(word0);
    let mut trees: Vec<CubeMerkleTree> = Vec::with_capacity(m);
    trees.push(word0_tree);
    let mut roots: Vec<Digest> = Vec::with_capacity(m + 1);
    roots.push(root0);
    let mut challenges: Vec<Tower256> = Vec::with_capacity(m);

    for j in 0..m {
        let input = roots_transcript_bytes(&head, &roots, j);
        let alpha = Tower256::from_le_bytes(xof32_alg(CHALLENGE_CUSTOMIZATION, &input));
        let half = 1usize << (ell - j - 1);
        let dom_lo = tabulate_subspace_domain(&beta, offset, ell - j - 1, &pivs[..j]);
        let pinv = piv_invs[j];
        let prev = &words[j];
        let mut next = Vec::with_capacity(half);
        for k in 0..half {
            let (lo, hi) = (prev[k], prev[k + half]);
            let t1 = dom_lo[k].add(alpha).mul(lo.add(hi));
            next.push(lo.add(t1.mul(pinv)));
        }
        challenges.push(alpha);
        if j + 1 < m {
            let tr = hasher.build_tree(&next, ell - (j + 1));
            roots.push(tr.root());
            trees.push(tr);
        }
        words.push(next);
    }

    let final_coeff = words[m][0];
    let final_coeffs = [final_coeff];
    let last_size = 1usize << (ell - m);
    let last_word = vec![final_coeff; last_size];
    let last_tree = hasher.build_tree(&last_word, ell - m);
    roots.push(last_tree.root());

    let mut prefix = roots_transcript_bytes(&head, &roots, m);
    for c in &challenges {
        envelope(&mut prefix, &c.to_le_bytes());
    }
    let seeds = derive_query_seeds_midstate(&prefix, ell, query_count);

    let mut out = Vec::new();
    encode_nat_255(&mut out, (m + 1) as u128);
    for r in &roots {
        encode_digest_stream(&mut out, r);
    }
    encode_nat_255(&mut out, m as u128);
    for c in &challenges {
        out.extend_from_slice(&c.to_le_bytes());
    }
    encode_nat_255(&mut out, query_count as u128);
    for &s in &seeds {
        encode_nat_255(&mut out, s as u128);
    }
    encode_nat_255(&mut out, m as u128);
    for j in 0..m {
        encode_nat_255(&mut out, query_count as u128);
        let w = &words[j];
        let tr = &trees[j];
        let half = 1usize << (ell - j - 1);
        for &s in &seeds {
            let k = s % half;
            out.extend_from_slice(&w[k].to_le_bytes());
            out.extend_from_slice(&w[k + half].to_le_bytes());
            let mut path = tr.path(k);
            path.pop();
            encode_nat_255(&mut out, path.len() as u128);
            for d in &path {
                encode_digest_stream(&mut out, d);
            }
        }
    }
    encode_nat_255(&mut out, final_coeffs.len() as u128);
    for c in &final_coeffs {
        out.extend_from_slice(&c.to_le_bytes());
    }

    CosetFriProveOutput {
        initial_root: root0,
        seeds,
        receipt_bytes: out,
    }
}

fn verify_coset_fri_receipt(
    hasher: &MerkleHasher,
    statement_bytes: &[u8],
    ell: usize,
    m: usize,
    initial_root: &Digest,
    final_degree_bound: usize,
    decoded: &DecodedFriReceipt,
) -> Result<(), PrivateCertError> {
    if &decoded.roots[0] != initial_root {
        return Err(PrivateCertError::VerificationFailed(
            "FRI root[0] != friInitialRoot",
        ));
    }
    if decoded.final_coeffs.len() > final_degree_bound {
        return Err(PrivateCertError::VerificationFailed(
            "FRI finalCoeffs exceeds final_degree_bound",
        ));
    }
    let beta = unit_basis(ell);
    let offset = coset_offset(ell);
    let mut head = Vec::new();
    envelope(&mut head, statement_bytes);
    envelope(&mut head, &basis_prefix_bytes(ell, m, &beta, offset));

    let mut pivots = Vec::with_capacity(m);
    for j in 0..m {
        let input = roots_transcript_bytes(&head, &decoded.roots, j);
        let expected_alpha = Tower256::from_le_bytes(xof32_alg(CHALLENGE_CUSTOMIZATION, &input));
        if decoded.challenges[j] != expected_alpha {
            return Err(PrivateCertError::VerificationFailed(
                "FRI Fiat-Shamir challenge mismatch",
            ));
        }
        let pivot = apply_pivots(&pivots, beta[(ell - 1).saturating_sub(j)]);
        pivots.push(pivot);
    }

    let last_size = 1usize << (ell - m);
    let last_word: Vec<Tower256> = (0..last_size)
        .map(|i| eval_horner(&decoded.final_coeffs, dom_point(&beta, offset, ell, m, &pivots, i)))
        .collect();
    let expected_last_root = hasher.build_tree(&last_word, ell - m).root();
    if decoded.roots[m] != expected_last_root {
        return Err(PrivateCertError::VerificationFailed("FRI lastRootC mismatch"));
    }

    let mut prefix = roots_transcript_bytes(&head, &decoded.roots, m);
    for c in &decoded.challenges {
        envelope(&mut prefix, &c.to_le_bytes());
    }
    let expected_seeds =
        derive_query_seeds_midstate(&prefix, ell, decoded.query_seeds.len());
    if decoded.query_seeds != expected_seeds {
        return Err(PrivateCertError::VerificationFailed("FRI query seed mismatch"));
    }

    for j in 0..m {
        let pivot_j = pivots[j];
        let half = 1usize << (ell - j - 1);
        for (a, &seed) in decoded.query_seeds.iter().enumerate() {
            let k = seed % half;
            let op = &decoded.openings[j][a];
            if !verify_pair_at_level(
                hasher,
                ell,
                j,
                &decoded.roots[j],
                k,
                op.left,
                op.right,
                &op.pair_path,
            ) {
                return Err(PrivateCertError::VerificationFailed(
                    "FRI pair Merkle path invalid",
                ));
            }
            let next_val = if j + 1 < m {
                let top_bit = (k >> (ell - (j + 1) - 1)) & 1;
                let next_op = &decoded.openings[j + 1][a];
                if top_bit == 0 {
                    next_op.left
                } else {
                    next_op.right
                }
            } else {
                last_word[k]
            };
            let dom_lo = dom_point(&beta, offset, ell, j, &pivots[..j], k);
            let lhs = next_val.add(op.left).mul(pivot_j);
            let rhs = dom_lo.add(decoded.challenges[j]).mul(op.left.add(op.right));
            if lhs != rhs {
                return Err(PrivateCertError::VerificationFailed(
                    "FRI fold equation failed",
                ));
            }
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
#[inline]
fn verify_pair_at_level(
    hasher: &MerkleHasher,
    ell: usize,
    j: usize,
    root: &Digest,
    k: usize,
    left_leaf: Tower256,
    right_leaf: Tower256,
    pair_path: &[Digest],
) -> bool {
    let depth = ell - j;
    if depth == 0 || pair_path.len() + 1 != depth || k >= (1usize << (depth - 1)) {
        return false;
    }
    let mut full = Vec::with_capacity(depth);
    full.extend_from_slice(pair_path);
    full.push(hasher.hash_leaf(right_leaf));
    hasher.verify_leaf(depth, root, k, left_leaf, &full)
}

/// Extract Fiat–Shamir derived FRI query seeds from an algebraic receipt (for conformance checks).
pub fn derived_fri_query_seeds(
    stmt: &AlgebraicContentCert,
    receipt: &AlgebraicPrivateReceipt,
) -> Result<Vec<usize>, PrivateCertError> {
    let decoded = decode_fri_receipt(
        &receipt.fri_receipt_bytes,
        stmt.fri_ell,
        stmt.cube_dim + 1,
        stmt.fri_queries,
    )?;
    Ok(decoded.query_seeds)
}

// ---------------------------------------------------------------------------------------------
// Core Algebraic Prover & Standalone Verifier (`proveAlgebraic` & `checkAlgebraic`)

struct AlgebraicMaskBundle {
    content_mask: Vec<Tower256>,
    p1_masks: Vec<Tower256>,
    mult_mask: Vec<Tower256>,
    p3_rand: Vec<Tower256>,
}

#[allow(clippy::too_many_arguments)]
fn prove_algebraic_core(
    dfa: &DfaTable,
    word: &[u8],
    claim: ClaimData,
    masks: AlgebraicMaskBundle,
    cube_dim: usize,
    fri_ell: usize,
    fri_queries: usize,
) -> Result<(AlgebraicContentCert, AlgebraicPrivateReceipt), PrivateCertError> {
    dfa.validate()?;
    if word.is_empty() {
        return Err(PrivateCertError::EmptyRecord);
    }
    let d = cube_dim;
    let fri_rounds = d + 1;
    if !(10..=22).contains(&d)
        || d + 2 > fri_ell
        || fri_ell > 24
        || word.len() > (1usize << d)
        || dfa.states * 256 > (1usize << d)
        || fri_queries == 0
        || 2 * fri_queries + 1 > (1usize << d)
    {
        return Err(PrivateCertError::InvalidShape(
            "require 10 <= cube_dim <= 22, cube_dim + 2 <= fri_ell <= 24, 2*fri_queries+1 <= 2^cube_dim",
        ));
    }
    let (final_s, run_cnt) = dfa.run_state_and_count(word);
    let final_acc = dfa.accepting[final_s];
    if !claim.decide(final_acc, run_cnt) {
        return Err(PrivateCertError::ClaimNotSatisfied {
            claim,
            final_accepted: final_acc,
            run_count: run_cnt as usize,
        });
    }

    let n_half = 1usize << d;
    let n_full = 1usize << (d + 1);
    if masks.content_mask.len() != n_half
        || masks.p1_masks.len() != 8 * n_half
        || masks.mult_mask.len() != n_half
        || masks.p3_rand.len() != 2 * n_half + 6 * n_full
    {
        return Err(PrivateCertError::RandomnessLengthMismatch);
    }

    let l = word.len();
    let m_tab = dfa.states * 256;
    let coset_len = 1usize << fri_ell;
    let zeta = zeta_c();
    let zeta_inv = zeta_inv_c();
    let zero = Tower256::ZERO;
    let one = Tower256::ONE;

    let hasher = MerkleHasher::new();
    let p1_leaf_hasher = VecLeafHasher::new(P1_LEAF_PREFIX, P1_LEAF_NAME);
    let p3_leaf_hasher = VecLeafHasher::new(P3_LEAF_PREFIX, P3_LEAF_NAME);
    let chal1_cust = prefixed_cust(CHAL1_PREFIX, CHAL1_NAME);
    let chal2_cust = prefixed_cust(CHAL2_PREFIX, CHAL2_NAME);
    let chal3_cust = prefixed_cust(CHAL3_PREFIX, CHAL3_NAME);
    let sc_chal_cust = prefixed_cust(SCCHAL_PREFIX, SCCHAL_NAME);
    let batch_cust = prefixed_cust(BATCH_PREFIX, BATCH_NAME);

    let (pivs, piv_invs) = compute_pivots_and_inverses(fri_ell, d + 1)?;
    let coset_thetas = precompute_coset_thetas(fri_ell, d + 1, &pivs, &piv_invs);

    let mut zeta_pows = Vec::with_capacity(d + 1);
    let mut z_cur = zeta;
    for _ in 0..=d {
        zeta_pows.push(z_cur);
        z_cur = z_cur.mul(zeta);
    }
    let zeta_dp1 = zeta_pows[d];
    let mut pub_lin_z = vec![zero; n_half];
    for (k, &zk) in zeta_pows.iter().enumerate().take(d) {
        let step = 1usize << k;
        for low in 0..step {
            pub_lin_z[low + step] = pub_lin_z[low].add(zk);
        }
    }

    // 1. Content column (`col 0`)
    let mut col0 = vec![zero; n_full];
    for (i, &b) in word.iter().enumerate() {
        col0[i] = leaf_of_u64(u64::from(b));
    }
    col0[n_half..n_full].copy_from_slice(&masks.content_mask);
    let coset0 = coset_encode_table_with_thetas(fri_ell, d + 1, &coset_thetas, &col0);
    let c_tree = hasher.build_tree(&coset0, fri_ell);
    let c_root = c_tree.root();

    // 2. Phase-1 columns (`cols 1..8`: `state, next, hit, cntPow, accLo, bitLo, accHi, bitHi`)
    let mut p1_tabs = vec![vec![zero; n_full]; 8];
    for c in 0..8 {
        p1_tabs[c][n_half..n_full].copy_from_slice(&masks.p1_masks[c * n_half..(c + 1) * n_half]);
    }
    let mut cur_s = dfa.initial;
    let mut cur_cc: u64 = 0;
    let mut cur_cnt_pow = one;
    let mut row_keys = Vec::with_capacity(l);
    for (i, &b) in word.iter().enumerate() {
        let key = 256 * cur_s + usize::from(b);
        row_keys.push(key);
        let nx = dfa.delta[key];
        let hit = u64::from(dfa.accepting[nx]);
        p1_tabs[0][i] = leaf_of_u64(cur_s as u64);
        p1_tabs[1][i] = leaf_of_u64(nx as u64);
        p1_tabs[2][i] = leaf_of_u64(hit);
        p1_tabs[3][i] = cur_cnt_pow;
        cur_cc += hit;
        if hit == 1 {
            cur_cnt_pow = cur_cnt_pow.mul(zeta);
        }
        cur_s = nx;
    }

    if let ClaimData::Bound { lo, hi } = claim {
        let hi_cap = hi.min(l as u64);
        let d1 = cur_cc - lo;
        let d2 = hi_cap - cur_cc;
        let mut a1 = pow_tower256(zeta, lo);
        let mut a2 = pow_tower256(zeta, hi_cap);
        let mut z1 = zeta;
        let mut z2 = zeta_inv;
        for k in 0..=d {
            let b1 = ((d1 >> k) & 1) == 1;
            let b2 = ((d2 >> k) & 1) == 1;
            p1_tabs[4][k] = a1;
            p1_tabs[5][k] = if b1 { one } else { zero };
            p1_tabs[6][k] = a2;
            p1_tabs[7][k] = if b2 { one } else { zero };
            if b1 {
                a1 = a1.mul(z1);
            }
            if b2 {
                a2 = a2.mul(z2);
            }
            z1 = z1.square();
            z2 = z2.square();
        }
    }

    let p1_cosets: Vec<Vec<Tower256>> = p1_tabs
        .iter()
        .map(|tab| coset_encode_table_with_thetas(fri_ell, d + 1, &coset_thetas, tab))
        .collect();
    let p1_leaves: Vec<Tower256> = (0..coset_len)
        .map(|idx| {
            let row = [
                p1_cosets[0][idx],
                p1_cosets[1][idx],
                p1_cosets[2][idx],
                p1_cosets[3][idx],
                p1_cosets[4][idx],
                p1_cosets[5][idx],
                p1_cosets[6][idx],
                p1_cosets[7][idx],
            ];
            p1_leaf_hasher.hash_cols(&row)
        })
        .collect();
    let p1_tree = hasher.build_tree(&p1_leaves, fri_ell);
    let p1_root = p1_tree.root();

    let stmt = AlgebraicContentCert {
        content_root: c_root,
        record_length: l,
        automaton_root: automaton_commit(dfa),
        claim,
        cube_dim: d,
        fri_ell,
        fri_queries,
    };

    // 3. Round-1 challenges (`alpha`, `theta`) + Phase-2 multiplicity column (`col 9`)
    let r1_bytes = alg_round1_transcript(&stmt, &p1_root);
    let alpha = derive_chal_at(&chal1_cust, &r1_bytes, 0);
    let theta = derive_chal_at(&chal1_cust, &r1_bytes, 1);

    let mut m_tab_col = vec![zero; n_full];
    let mut th_pow = one;
    for &k in &row_keys {
        m_tab_col[k] = m_tab_col[k].add(th_pow);
        th_pow = th_pow.mul(theta);
    }
    m_tab_col[n_half..n_full].copy_from_slice(&masks.mult_mask);
    let m_coset = coset_encode_table_with_thetas(fri_ell, d + 1, &coset_thetas, &m_tab_col);
    let m_tree = hasher.build_tree(&m_coset, fri_ell);
    let m_root = m_tree.root();

    // 4. Round-2 challenge (`gamma`) + Phase-3 columns (`cols 10..15` + `friMask`)
    let r2_bytes = alg_round2_transcript(&r1_bytes, &m_root);
    let gamma = derive_chal_at(&chal2_cust, &r2_bytes, 0);
    let alpha2 = alpha.square();
    let alpha3 = alpha2.mul(alpha);

    let mut tr_denoms = Vec::with_capacity(l);
    for i in 0..l {
        let e = col0[i]
            .add(alpha.mul(p1_tabs[0][i]))
            .add(alpha2.mul(p1_tabs[1][i]))
            .add(alpha3.mul(p1_tabs[2][i]));
        tr_denoms.push(gamma.add(e));
    }
    let tr_invs = batch_inverse256(&tr_denoms)?;

    let mut tab_denoms = Vec::with_capacity(m_tab);
    for k in 0..m_tab {
        let s = (k / 256) as u64;
        let b = (k % 256) as u64;
        let nx = dfa.delta[k];
        let hit = u64::from(dfa.accepting[nx]);
        let tk = leaf_of_u64(b)
            .add(alpha.mul(leaf_of_u64(s)))
            .add(alpha2.mul(leaf_of_u64(nx as u64)))
            .add(alpha3.mul(leaf_of_u64(hit)));
        tab_denoms.push(gamma.add(tk));
    }
    let tab_invs = batch_inverse256(&tab_denoms)?;

    let mut h_col = vec![zero; n_full];
    h_col[..l].copy_from_slice(&tr_invs);
    h_col[n_half..n_full].copy_from_slice(&masks.p3_rand[..n_half]);

    let mut g_col = vec![zero; n_full];
    g_col[..m_tab].copy_from_slice(&tab_invs);
    g_col[n_half..n_full].copy_from_slice(&masks.p3_rand[n_half..2 * n_half]);

    let off_base = 2 * n_half;
    let u1_tab = masks.p3_rand[off_base + n_full..off_base + 2 * n_full].to_vec();
    let u2_tab = masks.p3_rand[off_base + 2 * n_full..off_base + 3 * n_full].to_vec();
    let u3_tab = masks.p3_rand[off_base + 3 * n_full..off_base + 4 * n_full].to_vec();
    let bf_mask_tab = masks.p3_rand[off_base + 4 * n_full..off_base + 5 * n_full].to_vec();
    let fri_mask_tab = masks.p3_rand[off_base + 5 * n_full..off_base + 6 * n_full].to_vec();

    let mut m_lin_tab = vec![zero; n_full];
    let mut sum_m = zero;
    for idx in 0..(n_full - 1) {
        let v = masks.p3_rand[off_base + idx];
        m_lin_tab[idx] = v;
        sum_m = sum_m.add(v);
    }
    let mut sum_p1_u1 = zero;
    for i in 0..n_half {
        let p0 = pub_lin_z[i];
        let p1 = p0.add(zeta_dp1);
        sum_p1_u1 = sum_p1_u1
            .add(p0.mul(u1_tab[i]))
            .add(p1.mul(u1_tab[n_half + i]));
    }
    m_lin_tab[n_full - 1] = sum_m.add(sum_p1_u1);

    let p3_tabs = [
        &h_col,
        &g_col,
        &m_lin_tab,
        &u1_tab,
        &u2_tab,
        &u3_tab,
        &bf_mask_tab,
        &fri_mask_tab,
    ];
    let mut p3_cosets: Vec<Vec<Tower256>> = Vec::with_capacity(8);
    for tab in &p3_tabs {
        p3_cosets.push(coset_encode_table_with_thetas(fri_ell, d + 1, &coset_thetas, tab));
    }

    let p3_leaves: Vec<Tower256> = (0..coset_len)
        .map(|idx| {
            let row = [
                p3_cosets[0][idx],
                p3_cosets[1][idx],
                p3_cosets[2][idx],
                p3_cosets[3][idx],
                p3_cosets[4][idx],
                p3_cosets[5][idx],
                p3_cosets[6][idx],
                p3_cosets[7][idx],
            ];
            p3_leaf_hasher.hash_cols(&row)
        })
        .collect();
    let p3_tree = hasher.build_tree(&p3_leaves, fri_ell);
    let p3_root = p3_tree.root();

    // 5. Round-3 challenges & linear-time `(d + 1)`-round degree-`<= 4` sumcheck!
    let r3_bytes = alg_round3_transcript(&r2_bytes, &p3_root);
    let beta = derive_chal_at(&chal3_cust, &r3_bytes, 0);
    let tau_s = derive_chal_at(&chal3_cust, &r3_bytes, 1);
    let tau_c = derive_chal_at(&chal3_cust, &r3_bytes, 2);
    let tau_d = derive_chal_at(&chal3_cust, &r3_bytes, 3);
    let rho_lin = derive_chal_at(&chal3_cust, &r3_bytes, 4);
    if rho_lin == zero {
        return Err(PrivateCertError::InvalidShape("degenerate rho_lin == 0"));
    }

    let init_cols16: Vec<Vec<Tower256>> = vec![
        col0,
        p1_tabs[0].clone(),
        p1_tabs[1].clone(),
        p1_tabs[2].clone(),
        p1_tabs[3].clone(),
        p1_tabs[4].clone(),
        p1_tabs[5].clone(),
        p1_tabs[6].clone(),
        p1_tabs[7].clone(),
        m_tab_col,
        h_col,
        g_col,
        m_lin_tab,
        u1_tab,
        u2_tab,
        u3_tab,
    ];
    let mut cur_cols = init_cols16.clone();

    let mk_pow_prefix = |bound: usize, base: Tower256, scale: Tower256| -> Vec<Tower256> {
        let mut arr = vec![zero; n_half];
        let mut p = scale;
        for slot in arr.iter_mut().take(bound) {
            *slot = p;
            p = p.mul(base);
        }
        arr
    };

    let mut pub0 = vec![zero; n_half];
    pub0[0] = one;
    let mut pub_last = vec![zero; n_half];
    pub_last[l - 1] = one;
    let mut pub_d = vec![zero; n_half];
    pub_d[d] = one;
    let pub_lt_s = mk_pow_prefix(l, tau_s, one);
    let pub_lm1_s = mk_pow_prefix(l - 1, tau_s, tau_s);
    let pub_lt_c = mk_pow_prefix(l, tau_c, one);
    let pub_lm1_c = mk_pow_prefix(l - 1, tau_c, tau_c);
    let pub_lt_d = mk_pow_prefix(l, tau_d, one);
    let pub_tab_d = mk_pow_prefix(m_tab, tau_d, one);
    let pub_lt_theta = mk_pow_prefix(l, theta, one);
    let pub_tab_one = mk_pow_prefix(m_tab, one, one);
    let mut pub_tab_gamma_d = vec![zero; n_half];
    let mut td_cur = one;
    for k in 0..m_tab {
        pub_tab_gamma_d[k] = td_cur.mul(tab_denoms[k]);
        td_cur = td_cur.mul(tau_d);
    }

    let is_bound = matches!(claim, ClaimData::Bound { .. });
    let pub_bit_d = if is_bound {
        mk_pow_prefix(d + 1, tau_d, one)
    } else {
        vec![zero; n_half]
    };
    let pub_bit_c = if is_bound {
        mk_pow_prefix(d + 1, tau_c, one)
    } else {
        vec![zero; n_half]
    };
    let pub_bit_prev_c = if is_bound {
        mk_pow_prefix(d, tau_c, tau_c)
    } else {
        vec![zero; n_half]
    };
    let mut pub_step1 = vec![zero; n_half];
    let mut pub_step2 = vec![zero; n_half];
    if is_bound {
        let mut tc_cur = tau_c;
        let mut z1 = zeta;
        let mut z2 = zeta_inv;
        for k in 0..d {
            pub_step1[k] = tc_cur.mul(one.add(z1));
            pub_step2[k] = tc_cur.mul(one.add(z2));
            tc_cur = tc_cur.mul(tau_c);
            z1 = z1.square();
            z2 = z2.square();
        }
    }

    let mut pub_tabs: Vec<Vec<Tower256>> = vec![
        pub0,
        pub_last,
        pub_d,
        pub_lt_s,
        pub_lm1_s,
        pub_lt_c,
        pub_lm1_c,
        pub_lt_d,
        pub_tab_gamma_d,
        pub_tab_d,
        pub_lt_theta,
        pub_tab_one,
        pub_bit_d,
        pub_bit_c,
        pub_bit_prev_c,
        pub_step1,
        pub_step2,
        pub_lin_z,
    ];

    let pts5 = [
        zero,
        one,
        leaf_of_u64(2),
        leaf_of_u64(3),
        leaf_of_u64(4),
    ];
    let init_f = leaf_of_u64(dfa.initial as u64);
    let mut sc_polys = Vec::with_capacity(d + 1);
    let mut r_full = Vec::with_capacity(d + 1);
    let mut sc_tr = r3_bytes.clone();
    let mut z2_prefix = zero;
    let mut z3_prefix = zero;

    for j in 0..d {
        let half_cube = 1usize << (d - 1 - j);
        let zj = zeta_pows[j];
        let mut evals5 = [zero; 5];
        for (p_idx, &t_pt) in pts5.iter().enumerate() {
            let t2 = t_pt.square();
            let t3 = t2.mul(t_pt);
            let z2_pt = z2_prefix.add(zj.mul(t2.add(t_pt)));
            let z3_pt = z3_prefix.add(zj.mul(t3.add(t2)));
            let mut sum_pt = zero;
            for tail in 0..half_cube {
                let idx0 = 2 * tail;
                let line_at = |arr: &[Tower256], base: usize| -> Tower256 {
                    let v0 = arr[base];
                    let v1 = arr[base + 1];
                    v0.add(t_pt.mul(v0.add(v1)))
                };
                let mut ys0 = [zero; 16];
                for c in 0..16 {
                    ys0[c] = line_at(&cur_cols[c], idx0);
                }
                let mut ps = [zero; 18];
                for c in 0..18 {
                    ps[c] = line_at(&pub_tabs[c], idx0);
                }
                let v_half0 = eval_combined_phi(
                    claim, l, d, init_f, zeta, zeta_inv, alpha, gamma, beta, rho_lin, zero,
                    zeta_dp1, ps[17], z2_pt, z3_pt, &ps, &ys0,
                );
                let base_hi = 2 * half_cube + idx0;
                let m_lin1 = line_at(&cur_cols[12], base_hi);
                let u1_1 = line_at(&cur_cols[13], base_hi);
                let u2_1 = line_at(&cur_cols[14], base_hi);
                let u3_1 = line_at(&cur_cols[15], base_hi);
                let p1_hi = ps[17].add(zeta_dp1);
                let mask_body1 = m_lin1
                    .add(p1_hi.mul(u1_1))
                    .add(z2_pt.mul(u2_1))
                    .add(z3_pt.mul(u3_1));
                let v_half1 = rho_lin.mul(mask_body1);
                sum_pt = sum_pt.add(v_half0).add(v_half1);
            }
            evals5[p_idx] = sum_pt;
        }
        let poly = interpolate_deg4(&evals5);
        sc_polys.push(poly);
        envelope(&mut sc_tr, &nat_coord_bytes(j as u64));
        let mut p_bytes = Vec::with_capacity(160);
        poly.encode_bytes(&mut p_bytes);
        envelope(&mut sc_tr, &p_bytes);
        let rj = Tower256::from_le_bytes(xof32_alg(&sc_chal_cust, &sc_tr));
        r_full.push(rj);
        let rj2 = rj.square();
        let rj3 = rj2.mul(rj);
        z2_prefix = z2_prefix.add(zj.mul(rj2.add(rj)));
        z3_prefix = z3_prefix.add(zj.mul(rj3.add(rj2)));

        for col in &mut cur_cols {
            let mut next = Vec::with_capacity(2 * half_cube);
            for tail in 0..(2 * half_cube) {
                let v0 = col[2 * tail];
                let v1 = col[2 * tail + 1];
                next.push(v0.add(rj.mul(v0.add(v1))));
            }
            *col = next;
        }
        for ptab in &mut pub_tabs {
            let mut next = Vec::with_capacity(half_cube);
            for tail in 0..half_cube {
                let v0 = ptab[2 * tail];
                let v1 = ptab[2 * tail + 1];
                next.push(v0.add(rj.mul(v0.add(v1))));
            }
            *ptab = next;
        }
    }

    // Round `d` (final sumcheck round over `x_d`)
    let mut ps_final = [zero; 18];
    for c in 0..18 {
        ps_final[c] = pub_tabs[c][0];
    }
    let mut evals_last = [zero; 5];
    for (p_idx, &t_pt) in pts5.iter().enumerate() {
        let t2 = t_pt.square();
        let t3 = t2.mul(t_pt);
        let z2_pt = z2_prefix.add(zeta_dp1.mul(t2.add(t_pt)));
        let z3_pt = z3_prefix.add(zeta_dp1.mul(t3.add(t2)));
        let mut ys_pt = [zero; 16];
        for c in 0..16 {
            let v0 = cur_cols[c][0];
            let v1 = cur_cols[c][1];
            ys_pt[c] = v0.add(t_pt.mul(v0.add(v1)));
        }
        evals_last[p_idx] = eval_combined_phi(
            claim, l, d, init_f, zeta, zeta_inv, alpha, gamma, beta, rho_lin, t_pt, zeta_dp1,
            ps_final[17], z2_pt, z3_pt, &ps_final, &ys_pt,
        );
    }
    let poly_last = interpolate_deg4(&evals_last);
    sc_polys.push(poly_last);
    envelope(&mut sc_tr, &nat_coord_bytes(d as u64));
    let mut p_last_bytes = Vec::with_capacity(160);
    poly_last.encode_bytes(&mut p_last_bytes);
    envelope(&mut sc_tr, &p_last_bytes);
    let rd = Tower256::from_le_bytes(xof32_alg(&sc_chal_cust, &sc_tr));
    if rd == zero || rd == one {
        return Err(PrivateCertError::InvalidShape("degenerate r_d in {0, 1}"));
    }
    r_full.push(rd);

    let mut eq_cur = tabulate_chi(d + 1, &r_full);
    let mut bf_mask_at_r = zero;
    for idx in 0..n_full {
        bf_mask_at_r = bf_mask_at_r.add(eq_cur[idx].mul(bf_mask_tab[idx]));
    }

    let mut col_evals_at_r = [zero; 17];
    for c in 0..16 {
        let v0 = cur_cols[c][0];
        let v1 = cur_cols[c][1];
        col_evals_at_r[c] = v0.add(rd.mul(v0.add(v1)));
    }
    col_evals_at_r[16] = bf_mask_at_r;

    // 6. Batching challenges (`eta`, `rho_bf`, `rho_fri`), interleaved `(d + 1)`-round BaseFold, & coset FRI!
    let batch_bytes = alg_batch_transcript(&r3_bytes, &sc_polys, &col_evals_at_r);
    let eta = derive_chal_at(&batch_cust, &batch_bytes, 0);
    let rho_bf = derive_chal_at(&batch_cust, &batch_bytes, 1);
    let rho_fri = derive_chal_at(&batch_cust, &batch_bytes, 2);
    if rho_bf == zero || rho_fri == zero {
        return Err(PrivateCertError::InvalidShape("degenerate rho_bf or rho_fri == 0"));
    }

    let all16_cosets: [&[Tower256]; 16] = [
        &coset0,
        &p1_cosets[0],
        &p1_cosets[1],
        &p1_cosets[2],
        &p1_cosets[3],
        &p1_cosets[4],
        &p1_cosets[5],
        &p1_cosets[6],
        &p1_cosets[7],
        &m_coset,
        &p3_cosets[0],
        &p3_cosets[1],
        &p3_cosets[2],
        &p3_cosets[3],
        &p3_cosets[4],
        &p3_cosets[5],
    ];
    let bf_mask_coset = &p3_cosets[6];
    let fri_mask_coset = &p3_cosets[7];

    let mut h_tab_cur: Vec<Tower256> = (0..n_full)
        .map(|idx| {
            let mut vals = [zero; 16];
            for c in 0..16 {
                vals[c] = init_cols16[c][idx];
            }
            bf_mask_tab[idx].add(rho_bf.mul(eval_horner(&vals, eta)))
        })
        .collect();

    let mut h_cur: Vec<Tower256> = (0..coset_len)
        .map(|idx| {
            let mut vals = [zero; 16];
            for c in 0..16 {
                vals[c] = all16_cosets[c][idx];
            }
            bf_mask_coset[idx].add(rho_bf.mul(eval_horner(&vals, eta)))
        })
        .collect();

    let bf_chal_cust = prefixed_cust(BFCHAL_PREFIX, BFCHAL_NAME);
    let beta_basis = unit_basis(fri_ell);
    let offset = coset_offset(fri_ell);
    let mut bf_polys = Vec::with_capacity(d + 1);
    let mut eval_words: Vec<Vec<Tower256>> = Vec::with_capacity(d);
    let mut eval_trees: Vec<CubeMerkleTree> = Vec::with_capacity(d);
    let mut eval_roots: Vec<Digest> = Vec::with_capacity(d);
    let mut bf_tr = batch_bytes.clone();
    let mut q_buf = Vec::with_capacity(96);

    for j in 0..=d {
        let half_tab = 1usize << (d - j);
        let mut c0 = zero;
        let mut c1 = zero;
        let mut c2 = zero;
        for tail in 0..half_tab {
            let e0 = eq_cur[2 * tail];
            let e1 = eq_cur[2 * tail + 1];
            let h0 = h_tab_cur[2 * tail];
            let h1 = h_tab_cur[2 * tail + 1];
            let de = e0.add(e1);
            let dh = h0.add(h1);
            let p0 = e0.mul(h0);
            let p1 = e1.mul(h1);
            let p2 = de.mul(dh);
            c0 = c0.add(p0);
            c1 = c1.add(p0.add(p1).add(p2));
            c2 = c2.add(p2);
        }
        let q_poly = PolyDeg2 { coeffs: [c0, c1, c2] };
        bf_polys.push(q_poly);
        envelope(&mut bf_tr, &nat_coord_bytes(j as u64));
        q_buf.clear();
        q_poly.encode_bytes(&mut q_buf);
        envelope(&mut bf_tr, &q_buf);
        let sj = Tower256::from_le_bytes(xof32_alg(&bf_chal_cust, &bf_tr));
        if sj == one.add(r_full[j]) {
            return Err(PrivateCertError::InvalidShape("degenerate basefold s_j == 1 + r_j"));
        }

        let mut next_eq = Vec::with_capacity(half_tab);
        let mut next_h_tab = Vec::with_capacity(half_tab);
        for tail in 0..half_tab {
            let e0 = eq_cur[2 * tail];
            let e1 = eq_cur[2 * tail + 1];
            next_eq.push(e0.add(sj.mul(e0.add(e1))));
            let h0 = h_tab_cur[2 * tail];
            let h1 = h_tab_cur[2 * tail + 1];
            next_h_tab.push(h0.add(sj.mul(h0.add(h1))));
        }
        eq_cur = next_eq;
        h_tab_cur = next_h_tab;

        let half_j = 1usize << (fri_ell - j - 1);
        let dom_lo = tabulate_subspace_domain(&beta_basis, offset, fri_ell - j - 1, &pivs[..j]);
        let piv_j = pivs[j];
        let pinv_j = piv_invs[j];
        let alpha_j = piv_j.mul(sj);
        let prev = h_cur;
        let mut next = Vec::with_capacity(half_j);
        for k in 0..half_j {
            let (lo, hi) = (prev[k], prev[k + half_j]);
            let t1 = dom_lo[k].add(alpha_j).mul(lo.add(hi));
            next.push(lo.add(t1.mul(pinv_j)));
        }
        if j < d {
            let tr = hasher.build_tree(&next, fri_ell - (j + 1));
            let rt = tr.root();
            envelope(&mut bf_tr, &rt);
            eval_roots.push(rt);
            eval_trees.push(tr);
            eval_words.push(next.clone());
        }
        h_cur = next;
    }

    let bf_final_coeff = h_tab_cur[0];
    debug_assert!(h_cur.iter().all(|&v| v == bf_final_coeff));
    envelope(&mut bf_tr, &bf_final_coeff.to_le_bytes());

    let fri_word0: Vec<Tower256> = (0..coset_len)
        .map(|idx| {
            let mut vals = [zero; 16];
            for c in 0..16 {
                vals[c] = all16_cosets[c][idx];
            }
            let batch_rho = eval_horner(&vals, rho_fri);
            fri_mask_coset[idx].add(rho_fri.mul(batch_rho))
        })
        .collect();

    let fri_out = prove_coset_fri_degree1(
        &hasher,
        &bf_tr,
        fri_ell,
        fri_rounds,
        fri_queries,
        &pivs,
        &piv_invs,
        fri_word0,
    );

    // 7. Extract coherent coset & `evalFold` pair openings at `fri_out.seeds`!
    let half0 = 1usize << (fri_ell - 1);
    let mut content_ops = Vec::with_capacity(fri_queries);
    let mut phase1_ops = Vec::with_capacity(fri_queries);
    let mut mult_ops = Vec::with_capacity(fri_queries);
    let mut phase3_ops = Vec::with_capacity(fri_queries);

    for &seed in &fri_out.seeds {
        let k0 = seed % half0;
        let mut c_path = c_tree.path(k0);
        c_path.pop();
        content_ops.push(CosetPairOpening {
            left: coset0[k0],
            right: coset0[k0 + half0],
            pair_path: c_path,
        });

        let mut p1_path = p1_tree.path(k0);
        p1_path.pop();
        let mut p1_l = [zero; 8];
        let mut p1_r = [zero; 8];
        for c in 0..8 {
            p1_l[c] = p1_cosets[c][k0];
            p1_r[c] = p1_cosets[c][k0 + half0];
        }
        phase1_ops.push(Phase1PairOpening {
            left_cols: p1_l,
            right_cols: p1_r,
            pair_path: p1_path,
        });

        let mut m_path = m_tree.path(k0);
        m_path.pop();
        mult_ops.push(CosetPairOpening {
            left: m_coset[k0],
            right: m_coset[k0 + half0],
            pair_path: m_path,
        });

        let mut p3_path = p3_tree.path(k0);
        p3_path.pop();
        let mut p3_l = [zero; 8];
        let mut p3_r = [zero; 8];
        for c in 0..8 {
            p3_l[c] = p3_cosets[c][k0];
            p3_r[c] = p3_cosets[c][k0 + half0];
        }
        phase3_ops.push(Phase3PairOpening {
            left_cols: p3_l,
            right_cols: p3_r,
            pair_path: p3_path,
        });
    }

    let mut eval_fold_ops = Vec::with_capacity(d);
    for j in 0..d {
        let half_next = 1usize << (fri_ell - (j + 1) - 1);
        let w = &eval_words[j];
        let tr = &eval_trees[j];
        let mut row_ops = Vec::with_capacity(fri_queries);
        for &seed in &fri_out.seeds {
            let kj = seed % half_next;
            let mut path = tr.path(kj);
            path.pop();
            row_ops.push(CosetPairOpening {
                left: w[kj],
                right: w[kj + half_next],
                pair_path: path,
            });
        }
        eval_fold_ops.push(row_ops);
    }

    let receipt = AlgebraicPrivateReceipt {
        dfa: dfa.clone(),
        phase1_root: p1_root,
        mult_root: m_root,
        phase3_root: p3_root,
        sumcheck_polys: sc_polys,
        col_evals_at_r,
        bf_polys,
        bf_final_coeff,
        eval_fold_roots: eval_roots,
        fri_initial_root: fri_out.initial_root,
        fri_receipt_bytes: fri_out.receipt_bytes,
        content_ops,
        phase1_ops,
        mult_ops,
        phase3_ops,
        eval_fold_ops,
    };
    Ok((stmt, receipt))
}

/// Prove an algebraic content certificate matching Lean's `proveAlgebraic` byte-for-byte.
pub fn prove_algebraic_with_lean_seed(
    dfa: &DfaTable,
    word: &[u8],
    claim: ClaimData,
    seed: u64,
    cube_dim: usize,
    fri_ell: usize,
    fri_queries: usize,
) -> Result<(AlgebraicContentCert, AlgebraicPrivateReceipt), PrivateCertError> {
    if word.is_empty() {
        return Err(PrivateCertError::EmptyRecord);
    }
    if !(10..=22).contains(&cube_dim) {
        return Err(PrivateCertError::InvalidShape("require 10 <= cube_dim <= 22"));
    }
    let n_half = 1usize << cube_dim;
    let n_full = 1usize << (cube_dim + 1);
    let masks = AlgebraicMaskBundle {
        content_mask: expand_lean_seed_c8("MINIDREGG/ALGCERT/CMASK/V1", seed, n_half),
        p1_masks: expand_lean_seed_c8("MINIDREGG/ALGCERT/P1MASK/V1", seed, 8 * n_half),
        mult_mask: expand_lean_seed_c8("MINIDREGG/ALGCERT/MMASK/V1", seed, n_half),
        p3_rand: expand_lean_seed_c8("MINIDREGG/ALGCERT/P3MASK/V1", seed, 2 * n_half + 6 * n_full),
    };
    prove_algebraic_core(dfa, word, claim, masks, cube_dim, fri_ell, fri_queries)
}

/// Production `UD-100` (`q = 148`, `log_blowup = 2`, rate `1/4`) zero-byte-leakage algebraic prover.
///
/// Uses `content_mask_seed` strictly for `content_root` (so multiple conjunctive DFA / count / bound
/// claims over the same document share the **exact** same `content_root`), and `proof_mask_seed`
/// for per-proof HVZK trace/sumcheck/BaseFold/FRI blinding!
pub fn prove_algebraic_document(
    dfa: &DfaTable,
    word: &[u8],
    claim: ClaimData,
    content_mask_seed: &Digest,
    proof_mask_seed: &Digest,
) -> Result<(AlgebraicContentCert, AlgebraicPrivateReceipt), PrivateCertError> {
    if word.is_empty() {
        return Err(PrivateCertError::EmptyRecord);
    }
    let cube_dim = depth_of(word.len())
        .max(depth_of(dfa.states.saturating_mul(256)))
        .max(10);
    let log_blowup = 2usize;
    let fri_ell = (cube_dim + 1) + log_blowup;
    let fri_queries = ud100_fri_queries(log_blowup);

    let n_half = 1usize << cube_dim;
    let n_full = 1usize << (cube_dim + 1);
    let masks = AlgebraicMaskBundle {
        content_mask: expand_digest_seed_c8("MINIDREGG/ALGCERT/CMASK/V1", content_mask_seed, n_half),
        p1_masks: expand_digest_seed_c8("MINIDREGG/ALGCERT/P1MASK/V1", proof_mask_seed, 8 * n_half),
        mult_mask: expand_digest_seed_c8("MINIDREGG/ALGCERT/MMASK/V1", proof_mask_seed, n_half),
        p3_rand: expand_digest_seed_c8(
            "MINIDREGG/ALGCERT/P3MASK/V1",
            proof_mask_seed,
            2 * n_half + 6 * n_full,
        ),
    };
    prove_algebraic_core(dfa, word, claim, masks, cube_dim, fri_ell, fri_queries)
}

/// Standalone zero-byte-leakage algebraic verifier (`checkAlgebraic` in Lean; `0` field inversions).
pub fn verify_algebraic_cert(
    stmt: &AlgebraicContentCert,
    receipt: &AlgebraicPrivateReceipt,
) -> Result<(), PrivateCertError> {
    let d = stmt.cube_dim;
    let fri_rounds = d + 1;
    let fq = stmt.fri_queries;

    if !(10..=22).contains(&d) || d + 2 > stmt.fri_ell || stmt.fri_ell > 24 {
        return Err(PrivateCertError::VerificationFailed("invalid cube_dim / fri_ell"));
    }
    if stmt.record_length == 0 || stmt.record_length > (1usize << d) {
        return Err(PrivateCertError::VerificationFailed(
            "record_length out of 1..=2^cube_dim",
        ));
    }
    if fq == 0 || 2 * fq + 1 > (1usize << d) {
        return Err(PrivateCertError::VerificationFailed(
            "fri_queries out of 1..=((2^cube_dim - 1)/2)",
        ));
    }
    match stmt.claim {
        ClaimData::Accept(_) => {}
        ClaimData::Count(n) => {
            if n > stmt.record_length as u64 {
                return Err(PrivateCertError::VerificationFailed("count > record_length"));
            }
        }
        ClaimData::Bound { lo, hi } => {
            if lo > hi || lo > stmt.record_length as u64 {
                return Err(PrivateCertError::VerificationFailed(
                    "bound violates lo <= hi && lo <= record_length",
                ));
            }
        }
    }

    receipt.dfa.validate()?;
    if receipt.dfa.states * 256 > (1usize << d) {
        return Err(PrivateCertError::VerificationFailed(
            "dfa.states * 256 > 2^cube_dim",
        ));
    }
    if automaton_commit(&receipt.dfa) != stmt.automaton_root {
        return Err(PrivateCertError::VerificationFailed("automatonRoot mismatch"));
    }
    if receipt.sumcheck_polys.len() != d + 1
        || receipt.bf_polys.len() != d + 1
        || receipt.eval_fold_roots.len() != d
        || receipt.content_ops.len() != fq
        || receipt.phase1_ops.len() != fq
        || receipt.mult_ops.len() != fq
        || receipt.phase3_ops.len() != fq
        || receipt.eval_fold_ops.len() != d
        || receipt.eval_fold_ops.iter().any(|row| row.len() != fq)
    {
        return Err(PrivateCertError::VerificationFailed(
            "receipt array length mismatch",
        ));
    }

    let chal1_cust = prefixed_cust(CHAL1_PREFIX, CHAL1_NAME);
    let chal2_cust = prefixed_cust(CHAL2_PREFIX, CHAL2_NAME);
    let chal3_cust = prefixed_cust(CHAL3_PREFIX, CHAL3_NAME);
    let sc_chal_cust = prefixed_cust(SCCHAL_PREFIX, SCCHAL_NAME);
    let batch_cust = prefixed_cust(BATCH_PREFIX, BATCH_NAME);

    let r1_bytes = alg_round1_transcript(stmt, &receipt.phase1_root);
    let alpha = derive_chal_at(&chal1_cust, &r1_bytes, 0);
    let theta = derive_chal_at(&chal1_cust, &r1_bytes, 1);
    let r2_bytes = alg_round2_transcript(&r1_bytes, &receipt.mult_root);
    let gamma = derive_chal_at(&chal2_cust, &r2_bytes, 0);
    let r3_bytes = alg_round3_transcript(&r2_bytes, &receipt.phase3_root);
    let beta = derive_chal_at(&chal3_cust, &r3_bytes, 0);
    let tau_s = derive_chal_at(&chal3_cust, &r3_bytes, 1);
    let tau_c = derive_chal_at(&chal3_cust, &r3_bytes, 2);
    let tau_d = derive_chal_at(&chal3_cust, &r3_bytes, 3);
    let rho_lin = derive_chal_at(&chal3_cust, &r3_bytes, 4);
    if rho_lin == Tower256::ZERO {
        return Err(PrivateCertError::VerificationFailed("sumcheck rho_lin == 0"));
    }

    // 1. Run `(d + 1)`-round Fiat-Shamir sumcheck verifier (`runSumcheckVerifier`)
    let mut sc_claim = Tower256::ZERO;
    let mut r_full = Vec::with_capacity(d + 1);
    let mut sc_tr = r3_bytes.clone();
    let mut p_buf = Vec::with_capacity(160);
    for (j, poly) in receipt.sumcheck_polys.iter().enumerate() {
        if poly.sum_bool() != sc_claim {
            return Err(PrivateCertError::VerificationFailed(
                "sumcheck round p(0) + p(1) != claim",
            ));
        }
        envelope(&mut sc_tr, &nat_coord_bytes(j as u64));
        p_buf.clear();
        poly.encode_bytes(&mut p_buf);
        envelope(&mut sc_tr, &p_buf);
        let rj = Tower256::from_le_bytes(xof32_alg(&sc_chal_cust, &sc_tr));
        sc_claim = poly.eval(rj);
        r_full.push(rj);
    }
    let rd = r_full[d];
    if rd == Tower256::ZERO || rd == Tower256::ONE {
        return Err(PrivateCertError::VerificationFailed("sumcheck r_d in {0, 1}"));
    }

    // 2. Verify terminal identity `evalTerminalPhiC(...) == sc_claim`
    let ys16: &[Tower256; 16] = receipt.col_evals_at_r[..16].try_into().expect("16");
    let phi_val = eval_terminal_phi(
        stmt,
        &receipt.dfa,
        alpha,
        theta,
        gamma,
        beta,
        tau_s,
        tau_c,
        tau_d,
        rho_lin,
        &r_full,
        ys16,
    );
    if phi_val != sc_claim {
        return Err(PrivateCertError::VerificationFailed(
            "terminal sumcheck identity Phi(r) != scFinalClaim",
        ));
    }

    // 3. Interleaved `(d + 1)`-round BaseFold verifier + `Tower256SuccinctCheck` coset FRI!
    let batch_bytes =
        alg_batch_transcript(&r3_bytes, &receipt.sumcheck_polys, &receipt.col_evals_at_r);
    let eta = derive_chal_at(&batch_cust, &batch_bytes, 0);
    let rho_bf = derive_chal_at(&batch_cust, &batch_bytes, 1);
    let rho_fri = derive_chal_at(&batch_cust, &batch_bytes, 2);
    if rho_bf == Tower256::ZERO || rho_fri == Tower256::ZERO {
        return Err(PrivateCertError::VerificationFailed(
            "batch rho_bf or rho_fri == 0",
        ));
    }
    let v_batch = eval_horner(ys16, eta);
    let v_bf_claimed = receipt.col_evals_at_r[16].add(rho_bf.mul(v_batch));
    let (s_bf, full_fri_stmt) = run_basefold_verifier(
        d,
        &batch_bytes,
        &r_full,
        &receipt.bf_polys,
        &receipt.eval_fold_roots,
        receipt.bf_final_coeff,
        v_bf_claimed,
    )?;

    let hasher = MerkleHasher::new();
    let p1_leaf_hasher = VecLeafHasher::new(P1_LEAF_PREFIX, P1_LEAF_NAME);
    let p3_leaf_hasher = VecLeafHasher::new(P3_LEAF_PREFIX, P3_LEAF_NAME);
    let decoded_fri = decode_fri_receipt(&receipt.fri_receipt_bytes, stmt.fri_ell, fri_rounds, fq)?;
    verify_coset_fri_receipt(
        &hasher,
        &full_fri_stmt,
        stmt.fri_ell,
        fri_rounds,
        &receipt.fri_initial_root,
        alg_degree_schedule(d, fri_rounds),
        &decoded_fri,
    )?;

    // 4. Verify coherent level-0 coset pair welds + `(d + 1)`-round `evalFold` chains (`0` inversions!)
    let ell = stmt.fri_ell;
    let beta_basis = unit_basis(ell);
    let offset = coset_offset(ell);
    let mut pivots = Vec::with_capacity(d + 1);
    for j in 0..=d {
        pivots.push(apply_pivots(&pivots, beta_basis[(ell - 1).saturating_sub(j)]));
    }

    let half0 = 1usize << (ell - 1);
    for (a, &seed) in decoded_fri.query_seeds.iter().enumerate() {
        let k0 = seed % half0;
        let c_op = &receipt.content_ops[a];
        let p1_op = &receipt.phase1_ops[a];
        let m_op = &receipt.mult_ops[a];
        let p3_op = &receipt.phase3_ops[a];
        let fri_op0 = &decoded_fri.openings[0][a];

        if !verify_pair_at_level(
            &hasher,
            ell,
            0,
            &stmt.content_root,
            k0,
            c_op.left,
            c_op.right,
            &c_op.pair_path,
        ) {
            return Err(PrivateCertError::VerificationFailed(
                "contentRoot coset pair opening invalid",
            ));
        }
        if !verify_pair_at_level(
            &hasher,
            ell,
            0,
            &receipt.phase1_root,
            k0,
            p1_leaf_hasher.hash_cols(&p1_op.left_cols),
            p1_leaf_hasher.hash_cols(&p1_op.right_cols),
            &p1_op.pair_path,
        ) {
            return Err(PrivateCertError::VerificationFailed(
                "phase1Root coset pair opening invalid",
            ));
        }
        if !verify_pair_at_level(
            &hasher,
            ell,
            0,
            &receipt.mult_root,
            k0,
            m_op.left,
            m_op.right,
            &m_op.pair_path,
        ) {
            return Err(PrivateCertError::VerificationFailed(
                "multRoot coset pair opening invalid",
            ));
        }
        if !verify_pair_at_level(
            &hasher,
            ell,
            0,
            &receipt.phase3_root,
            k0,
            p3_leaf_hasher.hash_cols(&p3_op.left_cols),
            p3_leaf_hasher.hash_cols(&p3_op.right_cols),
            &p3_op.pair_path,
        ) {
            return Err(PrivateCertError::VerificationFailed(
                "phase3Root coset pair opening invalid",
            ));
        }

        let mut left_all16 = [Tower256::ZERO; 16];
        let mut right_all16 = [Tower256::ZERO; 16];
        left_all16[0] = c_op.left;
        right_all16[0] = c_op.right;
        left_all16[1..9].copy_from_slice(&p1_op.left_cols);
        right_all16[1..9].copy_from_slice(&p1_op.right_cols);
        left_all16[9] = m_op.left;
        right_all16[9] = m_op.right;
        left_all16[10..16].copy_from_slice(&p3_op.left_cols[..6]);
        right_all16[10..16].copy_from_slice(&p3_op.right_cols[..6]);

        let expected_fri_l =
            p3_op.left_cols[7].add(rho_fri.mul(eval_horner(&left_all16, rho_fri)));
        let expected_fri_r =
            p3_op.right_cols[7].add(rho_fri.mul(eval_horner(&right_all16, rho_fri)));
        if fri_op0.left != expected_fri_l || fri_op0.right != expected_fri_r {
            return Err(PrivateCertError::VerificationFailed(
                "level-0 FRI leaf weld mismatch",
            ));
        }

        let h0_l = p3_op.left_cols[6].add(rho_bf.mul(eval_horner(&left_all16, eta)));
        let h0_r = p3_op.right_cols[6].add(rho_bf.mul(eval_horner(&right_all16, eta)));

        for j in 0..=d {
            let half_j = 1usize << (ell - j - 1);
            let kj = seed % half_j;
            let (cur_l, cur_r) = if j == 0 {
                (h0_l, h0_r)
            } else {
                let op_j = &receipt.eval_fold_ops[j - 1][a];
                if !verify_pair_at_level(
                    &hasher,
                    ell,
                    j,
                    &receipt.eval_fold_roots[j - 1],
                    kj,
                    op_j.left,
                    op_j.right,
                    &op_j.pair_path,
                ) {
                    return Err(PrivateCertError::VerificationFailed(
                        "evalFold Merkle pair path invalid",
                    ));
                }
                (op_j.left, op_j.right)
            };

            let next_val = if j < d {
                let next_op = &receipt.eval_fold_ops[j][a];
                let top_bit = (kj >> (ell - (j + 1) - 1)) & 1;
                if top_bit == 0 {
                    next_op.left
                } else {
                    next_op.right
                }
            } else {
                receipt.bf_final_coeff
            };

            let piv_j = pivots[j];
            let dom_lo = dom_point(&beta_basis, offset, ell, j, &pivots[..j], kj);
            let alpha_eval = piv_j.mul(s_bf[j]);
            let lhs = next_val.add(cur_l).mul(piv_j);
            let rhs = dom_lo.add(alpha_eval).mul(cur_l.add(cur_r));
            if lhs != rhs {
                return Err(PrivateCertError::VerificationFailed(
                    "basefold algebraic fold equation failed",
                ));
            }
        }
    }
    Ok(())
}

// ---------------------------------------------------------------------------------------------
// Canonical Binary Wire Codec (`AlgebraicPrivateReceipt` & `AlgebraicContentCert`)
//
// Uses deterministic bottom-up Octopus Merkle multiproof deduplication on sibling paths across the
// `fq` coherent queries so overlapping top-of-tree siblings are transmitted once instead of `fq`
// times, while `decode_algebraic_receipt` reconstructs the exact per-query `pair_path` vectors!

fn write_u32(out: &mut Vec<u8>, v: u32) {
    out.extend_from_slice(&v.to_le_bytes());
}

fn read_u32(r: &mut StreamReader<'_>) -> Result<u32, PrivateCertError> {
    Ok(u32::from_le_bytes(r.take(4)?.try_into().expect("4B")))
}

fn write_multiproof_paths<'a, I>(
    out: &mut Vec<u8>,
    pair_depth: usize,
    query_indices: &[usize],
    paths: I,
) where
    I: IntoIterator<Item = &'a [Digest]>,
{
    out.push(pair_depth as u8);
    if pair_depth == 0 || query_indices.is_empty() {
        return;
    }
    // `pair_path[lvl]` (`0 <= lvl < pair_depth`, `stride = 1 << lvl`) is the sibling subtree root of
    // `(k & ((1 << (lvl + 1)) - 1)) ^ stride`! If BOTH children of a node are queried, neither
    // sibling needs to be sent on the wire because the verifier recomputes both from their leaves!
    let path_vec: Vec<&[Digest]> = paths.into_iter().collect();
    debug_assert_eq!(path_vec.len(), query_indices.len());

    // Record for each level `0..pair_depth` which prefixes in `0..(1 << (lvl + 1))` are visited.
    let mut visited_by_lvl: Vec<std::collections::BTreeSet<usize>> = Vec::with_capacity(pair_depth);
    for lvl in 0..pair_depth {
        let mask = (1usize << (lvl + 1)) - 1;
        let mut set = std::collections::BTreeSet::new();
        for &k in query_indices {
            set.insert(k & mask);
        }
        visited_by_lvl.push(set);
    }

    for lvl in (0..pair_depth).rev() {
        let stride = 1usize << lvl;
        let mask = (1usize << (lvl + 1)) - 1;
        let visited = &visited_by_lvl[lvl];
        let mut emitted = std::collections::BTreeSet::new();
        for (q_idx, &k) in query_indices.iter().enumerate() {
            let my_prefix = k & mask;
            let sib_prefix = my_prefix ^ stride;
            if !visited.contains(&sib_prefix) && emitted.insert(sib_prefix) {
                out.extend_from_slice(&path_vec[q_idx][lvl]);
            }
        }
    }
}

fn read_multiproof_paths(
    r: &mut StreamReader<'_>,
    hasher: &MerkleHasher,
    query_indices: &[usize],
    leaf_pairs: &[(Tower256, Tower256)],
) -> Result<Vec<Vec<Digest>>, PrivateCertError> {
    let pair_depth = usize::from(r.byte()?);
    if pair_depth > 24 {
        return Err(PrivateCertError::MalformedWire("pair_depth > 24"));
    }
    let fq = query_indices.len();
    if fq == 0 {
        return Ok(Vec::new());
    }
    if pair_depth == 0 {
        return Ok(vec![Vec::new(); fq]);
    }

    // At `lvl = pair_depth` (`stride = 1 << pair_depth`), each `k < stride` has known left leaf
    // `leaf_pairs[q].0` and known right sibling `leaf_pairs[q].1` -> parent at `lvl = pair_depth - 1`
    // is NOT yet hashed until we know `lvl = pair_depth`: wait!
    // Recall `CubeMerkleTree::path(k)` at `lvl` (`0 <= lvl < depth = pair_depth + 1`):
    // - `lvl = pair_depth` (dropped by `.pop()`): sibling is `hash_leaf(right_leaf)` at `k + (1 << pair_depth)`,
    //   so node at `lvl = pair_depth` for prefix `k` (`0 <= k < 1 << pair_depth`) is
    //   `hash_node(hash_leaf(left), hash_leaf(right))`!
    let mut known_nodes: std::collections::BTreeMap<usize, Digest> =
        std::collections::BTreeMap::new();
    let top_mask = (1usize << pair_depth) - 1;
    for (&k, &(left, right)) in query_indices.iter().zip(leaf_pairs.iter()) {
        let pref = k & top_mask;
        known_nodes.entry(pref).or_insert_with(|| {
            let hl = hasher.hash_leaf(left);
            let hr = hasher.hash_leaf(right);
            hasher.hash_node(&hl, &hr)
        });
    }

    let mut per_query_paths = vec![vec![[0u8; 32]; pair_depth]; fq];
    for lvl in (0..pair_depth).rev() {
        let stride = 1usize << lvl;
        let mask = (1usize << (lvl + 1)) - 1;
        let parent_mask = stride - 1;
        let mut visited = std::collections::BTreeSet::new();
        for &k in query_indices {
            visited.insert(k & mask);
        }
        let mut level_sibs: std::collections::BTreeMap<usize, Digest> =
            std::collections::BTreeMap::new();
        for &k in query_indices {
            let my_prefix = k & mask;
            let sib_prefix = my_prefix ^ stride;
            if !visited.contains(&sib_prefix) && !level_sibs.contains_key(&sib_prefix) {
                let d: Digest = r.take(32)?.try_into().expect("32B");
                level_sibs.insert(sib_prefix, d);
            }
        }
        for (q_idx, &k) in query_indices.iter().enumerate() {
            let my_prefix = k & mask;
            let sib_prefix = my_prefix ^ stride;
            let sib = if let Some(&d) = known_nodes.get(&sib_prefix) {
                d
            } else {
                *level_sibs
                    .get(&sib_prefix)
                    .ok_or(PrivateCertError::MalformedWire("missing multiproof sibling"))?
            };
            per_query_paths[q_idx][lvl] = sib;
        }
        let mut next_nodes = std::collections::BTreeMap::new();
        for &my_prefix in &visited {
            let parent_pref = my_prefix & parent_mask;
            if next_nodes.contains_key(&parent_pref) {
                continue;
            }
            let left_pref = parent_pref;
            let right_pref = parent_pref | stride;
            let l_dig = known_nodes
                .get(&left_pref)
                .or_else(|| level_sibs.get(&left_pref))
                .ok_or(PrivateCertError::MalformedWire("missing left node"))?;
            let r_dig = known_nodes
                .get(&right_pref)
                .or_else(|| level_sibs.get(&right_pref))
                .ok_or(PrivateCertError::MalformedWire("missing right node"))?;
            next_nodes.insert(parent_pref, hasher.hash_node(l_dig, r_dig));
        }
        known_nodes = next_nodes;
    }
    Ok(per_query_paths)
}

fn encode_decoded_fri_receipt(
    m: usize,
    query_count: usize,
    roots: &[Digest],
    challenges: &[Tower256],
    seeds: &[usize],
    openings: &[Vec<CosetPairOpening>],
    final_coeffs: &[Tower256],
) -> Vec<u8> {
    let mut out = Vec::new();
    encode_nat_255(&mut out, (m + 1) as u128);
    for r in roots {
        encode_digest_stream(&mut out, r);
    }
    encode_nat_255(&mut out, m as u128);
    for c in challenges {
        out.extend_from_slice(&c.to_le_bytes());
    }
    encode_nat_255(&mut out, query_count as u128);
    for &s in seeds {
        encode_nat_255(&mut out, s as u128);
    }
    encode_nat_255(&mut out, m as u128);
    for round_ops in openings.iter().take(m) {
        encode_nat_255(&mut out, query_count as u128);
        for op in round_ops {
            out.extend_from_slice(&op.left.to_le_bytes());
            out.extend_from_slice(&op.right.to_le_bytes());
            encode_nat_255(&mut out, op.pair_path.len() as u128);
            for d in &op.pair_path {
                encode_digest_stream(&mut out, d);
            }
        }
    }
    encode_nat_255(&mut out, final_coeffs.len() as u128);
    for c in final_coeffs {
        out.extend_from_slice(&c.to_le_bytes());
    }
    out
}

/// Encode an `AlgebraicPrivateReceipt` into canonical Octopus-deduplicated wire bytes
/// (deduplicating sibling paths across all 4 coset trees, all `d` BaseFold trees, AND all `d + 1`
/// `Tower256SuccinctCheck` coset-FRI trees while reconstructing the exact `receiptStream` on decode!).
pub fn encode_algebraic_receipt(
    stmt: &AlgebraicContentCert,
    receipt: &AlgebraicPrivateReceipt,
) -> Result<Vec<u8>, PrivateCertError> {
    let d = stmt.cube_dim;
    let m = d + 1;
    let ell = stmt.fri_ell;
    let fq = stmt.fri_queries;
    let decoded_fri = decode_fri_receipt(&receipt.fri_receipt_bytes, ell, m, fq)?;
    if decoded_fri.roots[0] != receipt.fri_initial_root || decoded_fri.final_coeffs.len() > 255 {
        return Err(PrivateCertError::MalformedWire("FRI root[0] or final_coeffs mismatch"));
    }
    let seeds = &decoded_fri.query_seeds;

    let mut out = Vec::new();
    out.extend_from_slice(ALG_RECEIPT_MAGIC);
    write_u32(&mut out, receipt.dfa.states as u32);
    write_u32(&mut out, receipt.dfa.initial as u32);
    for &acc in &receipt.dfa.accepting {
        out.push(if acc { 1 } else { 0 });
    }
    for &nx in &receipt.dfa.delta {
        out.extend_from_slice(&(nx as u16).to_le_bytes());
    }
    out.extend_from_slice(&receipt.phase1_root);
    out.extend_from_slice(&receipt.mult_root);
    out.extend_from_slice(&receipt.phase3_root);

    write_u32(&mut out, receipt.sumcheck_polys.len() as u32);
    for poly in &receipt.sumcheck_polys {
        poly.encode_bytes(&mut out);
    }
    for y in &receipt.col_evals_at_r {
        out.extend_from_slice(&y.to_le_bytes());
    }
    write_u32(&mut out, receipt.bf_polys.len() as u32);
    for q in &receipt.bf_polys {
        q.encode_bytes(&mut out);
    }
    out.extend_from_slice(&receipt.bf_final_coeff.to_le_bytes());
    write_u32(&mut out, receipt.eval_fold_roots.len() as u32);
    for r in &receipt.eval_fold_roots {
        out.extend_from_slice(r);
    }
    out.extend_from_slice(&receipt.fri_initial_root);
    for r in &decoded_fri.roots[1..] {
        out.extend_from_slice(r);
    }
    out.push(decoded_fri.final_coeffs.len() as u8);
    for c in &decoded_fri.final_coeffs {
        out.extend_from_slice(&c.to_le_bytes());
    }

    let half0 = 1usize << (ell - 1);
    let idx0: Vec<usize> = seeds.iter().map(|&s| s % half0).collect();

    for op in &receipt.content_ops {
        out.extend_from_slice(&op.left.to_le_bytes());
        out.extend_from_slice(&op.right.to_le_bytes());
    }
    write_multiproof_paths(
        &mut out,
        ell - 1,
        &idx0,
        receipt.content_ops.iter().map(|op| op.pair_path.as_slice()),
    );

    for op in &receipt.phase1_ops {
        for c in &op.left_cols {
            out.extend_from_slice(&c.to_le_bytes());
        }
        for c in &op.right_cols {
            out.extend_from_slice(&c.to_le_bytes());
        }
    }
    write_multiproof_paths(
        &mut out,
        ell - 1,
        &idx0,
        receipt.phase1_ops.iter().map(|op| op.pair_path.as_slice()),
    );

    for op in &receipt.mult_ops {
        out.extend_from_slice(&op.left.to_le_bytes());
        out.extend_from_slice(&op.right.to_le_bytes());
    }
    write_multiproof_paths(
        &mut out,
        ell - 1,
        &idx0,
        receipt.mult_ops.iter().map(|op| op.pair_path.as_slice()),
    );

    for op in &receipt.phase3_ops {
        for c in &op.left_cols {
            out.extend_from_slice(&c.to_le_bytes());
        }
        for c in &op.right_cols {
            out.extend_from_slice(&c.to_le_bytes());
        }
    }
    write_multiproof_paths(
        &mut out,
        ell - 1,
        &idx0,
        receipt.phase3_ops.iter().map(|op| op.pair_path.as_slice()),
    );

    for (j, row) in receipt.eval_fold_ops.iter().enumerate() {
        let pair_depth = ell - (j + 1) - 1;
        let half_next = 1usize << pair_depth;
        let idx_j: Vec<usize> = seeds.iter().map(|&s| s % half_next).collect();
        for op in row {
            out.extend_from_slice(&op.left.to_le_bytes());
            out.extend_from_slice(&op.right.to_le_bytes());
        }
        write_multiproof_paths(
            &mut out,
            pair_depth,
            &idx_j,
            row.iter().map(|op| op.pair_path.as_slice()),
        );
    }

    for (j, round_ops) in decoded_fri.openings.iter().enumerate() {
        let pair_depth = ell - j - 1;
        let half_j = 1usize << pair_depth;
        let idx_j: Vec<usize> = seeds.iter().map(|&s| s % half_j).collect();
        for op in round_ops {
            out.extend_from_slice(&op.left.to_le_bytes());
            out.extend_from_slice(&op.right.to_le_bytes());
        }
        write_multiproof_paths(
            &mut out,
            pair_depth,
            &idx_j,
            round_ops.iter().map(|op| op.pair_path.as_slice()),
        );
    }

    Ok(out)
}

/// Decode an `AlgebraicPrivateReceipt` from canonical Octopus-deduplicated wire bytes.
pub fn decode_algebraic_receipt(
    stmt: &AlgebraicContentCert,
    bytes: &[u8],
) -> Result<AlgebraicPrivateReceipt, PrivateCertError> {
    let d = stmt.cube_dim;
    let m = d + 1;
    let ell = stmt.fri_ell;
    let fq = stmt.fri_queries;
    if !(10..=22).contains(&d) || d + 2 > ell || ell > 24 || fq == 0 || 2 * fq + 1 > (1usize << d) {
        return Err(PrivateCertError::MalformedWire("invalid statement dimensions"));
    }

    let mut r = StreamReader { bytes, pos: 0 };
    if r.take(8)? != ALG_RECEIPT_MAGIC {
        return Err(PrivateCertError::MalformedWire("bad algebraic receipt magic"));
    }
    let states = read_u32(&mut r)? as usize;
    if states == 0 || states > (1 << 16) {
        return Err(PrivateCertError::MalformedWire("states out of range"));
    }
    let initial = read_u32(&mut r)? as usize;
    let acc_raw = r.take(states)?;
    let mut accepting = Vec::with_capacity(states);
    for &b in acc_raw {
        match b {
            0 => accepting.push(false),
            1 => accepting.push(true),
            _ => return Err(PrivateCertError::MalformedWire("non-boolean accepting byte")),
        }
    }
    let delta_bytes = r.take(states * 256 * 2)?;
    let delta: Vec<usize> = delta_bytes
        .chunks_exact(2)
        .map(|c| usize::from(u16::from_le_bytes([c[0], c[1]])))
        .collect();
    let dfa = DfaTable {
        states,
        initial,
        accepting,
        delta,
    };

    let phase1_root: Digest = r.take(32)?.try_into().expect("32B");
    let mult_root: Digest = r.take(32)?.try_into().expect("32B");
    let phase3_root: Digest = r.take(32)?.try_into().expect("32B");

    let n_sc = read_u32(&mut r)? as usize;
    if n_sc != d + 1 {
        return Err(PrivateCertError::MalformedWire("wrong sumcheck_polys len"));
    }
    let mut sumcheck_polys = Vec::with_capacity(n_sc);
    for _ in 0..n_sc {
        let coeffs = [r.c8()?, r.c8()?, r.c8()?, r.c8()?, r.c8()?];
        sumcheck_polys.push(PolyDeg4 { coeffs });
    }
    let mut col_evals_at_r = [Tower256::ZERO; 17];
    for slot in &mut col_evals_at_r {
        *slot = r.c8()?;
    }
    let n_bf = read_u32(&mut r)? as usize;
    if n_bf != d + 1 {
        return Err(PrivateCertError::MalformedWire("wrong bf_polys len"));
    }
    let mut bf_polys = Vec::with_capacity(n_bf);
    for _ in 0..n_bf {
        let coeffs = [r.c8()?, r.c8()?, r.c8()?];
        bf_polys.push(PolyDeg2 { coeffs });
    }
    let bf_final_coeff = r.c8()?;

    let n_ef_roots = read_u32(&mut r)? as usize;
    if n_ef_roots != d {
        return Err(PrivateCertError::MalformedWire("wrong eval_fold_roots len"));
    }
    let mut eval_fold_roots = Vec::with_capacity(d);
    for _ in 0..d {
        eval_fold_roots.push(r.take(32)?.try_into().expect("32B"));
    }
    let fri_initial_root: Digest = r.take(32)?.try_into().expect("32B");
    let mut fri_roots = Vec::with_capacity(m + 1);
    fri_roots.push(fri_initial_root);
    for _ in 0..m {
        fri_roots.push(r.take(32)?.try_into().expect("32B"));
    }
    let n_final = usize::from(r.byte()?);
    if n_final > (1usize << (ell - m)) {
        return Err(PrivateCertError::MalformedWire("too many final coeffs"));
    }
    let final_coeffs = (0..n_final).map(|_| r.c8()).collect::<Result<Vec<_>, _>>()?;

    // Reconstruct deterministic Fiat-Shamir FRI challenges & query seeds from the header!
    let r1_bytes = alg_round1_transcript(stmt, &phase1_root);
    let r2_bytes = alg_round2_transcript(&r1_bytes, &mult_root);
    let r3_bytes = alg_round3_transcript(&r2_bytes, &phase3_root);
    let batch_bytes = alg_batch_transcript(&r3_bytes, &sumcheck_polys, &col_evals_at_r);
    let (_, full_fri_stmt) = build_basefold_transcript(
        d,
        &batch_bytes,
        &bf_polys,
        &eval_fold_roots,
        bf_final_coeff,
    );
    let beta = unit_basis(ell);
    let offset = coset_offset(ell);
    let mut head = Vec::new();
    envelope(&mut head, &full_fri_stmt);
    envelope(&mut head, &basis_prefix_bytes(ell, m, &beta, offset));
    let mut fri_challenges = Vec::with_capacity(m);
    for j in 0..m {
        let input = roots_transcript_bytes(&head, &fri_roots, j);
        fri_challenges.push(Tower256::from_le_bytes(xof32_alg(CHALLENGE_CUSTOMIZATION, &input)));
    }
    let mut prefix = roots_transcript_bytes(&head, &fri_roots, m);
    for c in &fri_challenges {
        envelope(&mut prefix, &c.to_le_bytes());
    }
    let seeds = derive_query_seeds_midstate(&prefix, ell, fq);

    let hasher = MerkleHasher::new();
    let p1_leaf_hasher = VecLeafHasher::new(P1_LEAF_PREFIX, P1_LEAF_NAME);
    let p3_leaf_hasher = VecLeafHasher::new(P3_LEAF_PREFIX, P3_LEAF_NAME);
    let half0 = 1usize << (ell - 1);
    let idx0: Vec<usize> = seeds.iter().map(|&s| s % half0).collect();

    let mut c_pairs = Vec::with_capacity(fq);
    for _ in 0..fq {
        c_pairs.push((r.c8()?, r.c8()?));
    }
    let c_paths = read_multiproof_paths(&mut r, &hasher, &idx0, &c_pairs)?;
    let content_ops: Vec<CosetPairOpening> = c_pairs
        .into_iter()
        .zip(c_paths)
        .map(|((left, right), pair_path)| CosetPairOpening {
            left,
            right,
            pair_path,
        })
        .collect();

    let mut p1_cols = Vec::with_capacity(fq);
    let mut p1_leaf_pairs = Vec::with_capacity(fq);
    for _ in 0..fq {
        let mut l = [Tower256::ZERO; 8];
        let mut rr = [Tower256::ZERO; 8];
        for slot in &mut l {
            *slot = r.c8()?;
        }
        for slot in &mut rr {
            *slot = r.c8()?;
        }
        p1_leaf_pairs.push((p1_leaf_hasher.hash_cols(&l), p1_leaf_hasher.hash_cols(&rr)));
        p1_cols.push((l, rr));
    }
    let p1_paths = read_multiproof_paths(&mut r, &hasher, &idx0, &p1_leaf_pairs)?;
    let phase1_ops: Vec<Phase1PairOpening> = p1_cols
        .into_iter()
        .zip(p1_paths)
        .map(|((left_cols, right_cols), pair_path)| Phase1PairOpening {
            left_cols,
            right_cols,
            pair_path,
        })
        .collect();

    let mut m_pairs = Vec::with_capacity(fq);
    for _ in 0..fq {
        m_pairs.push((r.c8()?, r.c8()?));
    }
    let m_paths = read_multiproof_paths(&mut r, &hasher, &idx0, &m_pairs)?;
    let mult_ops: Vec<CosetPairOpening> = m_pairs
        .into_iter()
        .zip(m_paths)
        .map(|((left, right), pair_path)| CosetPairOpening {
            left,
            right,
            pair_path,
        })
        .collect();

    let mut p3_cols = Vec::with_capacity(fq);
    let mut p3_leaf_pairs = Vec::with_capacity(fq);
    for _ in 0..fq {
        let mut l = [Tower256::ZERO; 8];
        let mut rr = [Tower256::ZERO; 8];
        for slot in &mut l {
            *slot = r.c8()?;
        }
        for slot in &mut rr {
            *slot = r.c8()?;
        }
        p3_leaf_pairs.push((p3_leaf_hasher.hash_cols(&l), p3_leaf_hasher.hash_cols(&rr)));
        p3_cols.push((l, rr));
    }
    let p3_paths = read_multiproof_paths(&mut r, &hasher, &idx0, &p3_leaf_pairs)?;
    let phase3_ops: Vec<Phase3PairOpening> = p3_cols
        .into_iter()
        .zip(p3_paths)
        .map(|((left_cols, right_cols), pair_path)| Phase3PairOpening {
            left_cols,
            right_cols,
            pair_path,
        })
        .collect();

    let mut eval_fold_ops = Vec::with_capacity(d);
    for j in 0..d {
        let pair_depth = ell - (j + 1) - 1;
        let half_next = 1usize << pair_depth;
        let idx_j: Vec<usize> = seeds.iter().map(|&s| s % half_next).collect();
        let mut pairs = Vec::with_capacity(fq);
        for _ in 0..fq {
            pairs.push((r.c8()?, r.c8()?));
        }
        let paths = read_multiproof_paths(&mut r, &hasher, &idx_j, &pairs)?;
        let row: Vec<CosetPairOpening> = pairs
            .into_iter()
            .zip(paths)
            .map(|((left, right), pair_path)| CosetPairOpening {
                left,
                right,
                pair_path,
            })
            .collect();
        eval_fold_ops.push(row);
    }

    let mut fri_openings = Vec::with_capacity(m);
    for j in 0..m {
        let pair_depth = ell - j - 1;
        let half_j = 1usize << pair_depth;
        let idx_j: Vec<usize> = seeds.iter().map(|&s| s % half_j).collect();
        let mut pairs = Vec::with_capacity(fq);
        for _ in 0..fq {
            pairs.push((r.c8()?, r.c8()?));
        }
        let paths = read_multiproof_paths(&mut r, &hasher, &idx_j, &pairs)?;
        let row: Vec<CosetPairOpening> = pairs
            .into_iter()
            .zip(paths)
            .map(|((left, right), pair_path)| CosetPairOpening {
                left,
                right,
                pair_path,
            })
            .collect();
        fri_openings.push(row);
    }

    if r.pos != bytes.len() {
        return Err(PrivateCertError::MalformedWire(
            "trailing bytes in AlgebraicPrivateReceipt",
        ));
    }

    let fri_receipt_bytes = encode_decoded_fri_receipt(
        m,
        fq,
        &fri_roots,
        &fri_challenges,
        &seeds,
        &fri_openings,
        &final_coeffs,
    );

    Ok(AlgebraicPrivateReceipt {
        dfa,
        phase1_root,
        mult_root,
        phase3_root,
        sumcheck_polys,
        col_evals_at_r,
        bf_polys,
        bf_final_coeff,
        eval_fold_roots,
        fri_initial_root,
        fri_receipt_bytes,
        content_ops,
        phase1_ops,
        mult_ops,
        phase3_ops,
        eval_fold_ops,
    })
}

pub fn verify_algebraic_cert_bytes(
    stmt: &AlgebraicContentCert,
    receipt_bytes: &[u8],
) -> Result<(), PrivateCertError> {
    let receipt = decode_algebraic_receipt(stmt, receipt_bytes)?;
    verify_algebraic_cert(stmt, &receipt)
}

pub fn encode_algebraic_cert(stmt: &AlgebraicContentCert) -> Vec<u8> {
    let mut out = Vec::with_capacity(112);
    out.extend_from_slice(ALG_STMT_MAGIC);
    out.extend_from_slice(&stmt.content_root);
    out.extend_from_slice(&(stmt.record_length as u64).to_le_bytes());
    out.extend_from_slice(&stmt.automaton_root);
    match stmt.claim {
        ClaimData::Accept(b) => {
            out.push(0);
            out.push(if b { 1 } else { 0 });
        }
        ClaimData::Count(n) => {
            out.push(1);
            out.extend_from_slice(&n.to_le_bytes());
        }
        ClaimData::Bound { lo, hi } => {
            out.push(2);
            out.extend_from_slice(&lo.to_le_bytes());
            out.extend_from_slice(&hi.to_le_bytes());
        }
    }
    write_u32(&mut out, stmt.cube_dim as u32);
    write_u32(&mut out, stmt.fri_ell as u32);
    write_u32(&mut out, stmt.fri_queries as u32);
    out
}

pub fn decode_algebraic_cert(bytes: &[u8]) -> Result<AlgebraicContentCert, PrivateCertError> {
    let mut r = StreamReader { bytes, pos: 0 };
    if r.take(8)? != ALG_STMT_MAGIC {
        return Err(PrivateCertError::MalformedWire("bad algebraic statement magic"));
    }
    let content_root: Digest = r.take(32)?.try_into().expect("32B");
    let record_length = u64::from_le_bytes(r.take(8)?.try_into().expect("8B")) as usize;
    let automaton_root: Digest = r.take(32)?.try_into().expect("32B");
    let claim = match r.byte()? {
        0 => match r.byte()? {
            0 => ClaimData::Accept(false),
            1 => ClaimData::Accept(true),
            _ => return Err(PrivateCertError::MalformedWire("bad accept bool")),
        },
        1 => ClaimData::Count(u64::from_le_bytes(r.take(8)?.try_into().expect("8B"))),
        2 => {
            let lo = u64::from_le_bytes(r.take(8)?.try_into().expect("8B"));
            let hi = u64::from_le_bytes(r.take(8)?.try_into().expect("8B"));
            ClaimData::Bound { lo, hi }
        }
        _ => return Err(PrivateCertError::MalformedWire("bad claim tag")),
    };
    let cube_dim = read_u32(&mut r)? as usize;
    let fri_ell = read_u32(&mut r)? as usize;
    let fri_queries = read_u32(&mut r)? as usize;
    if r.pos != bytes.len() {
        return Err(PrivateCertError::MalformedWire(
            "trailing bytes in AlgebraicContentCert",
        ));
    }
    Ok(AlgebraicContentCert {
        content_root,
        record_length,
        automaton_root,
        claim,
        cube_dim,
        fri_ell,
        fri_queries,
    })
}

/// Extract the non-public payload portion of an encoded `AlgebraicPrivateReceipt` (stripping the
/// public `DfaTable` header) for strict private-byte / 1-byte-pin zero-leakage scanning.
pub fn strip_public_dfa_from_wire<'a>(
    stmt: &AlgebraicContentCert,
    wire: &'a [u8],
) -> Result<&'a [u8], PrivateCertError> {
    let _ = stmt;
    if wire.len() < 16 || &wire[..8] != ALG_RECEIPT_MAGIC {
        return Err(PrivateCertError::MalformedWire("bad magic in strip"));
    }
    let states = u32::from_le_bytes(wire[8..12].try_into().expect("4B")) as usize;
    let dfa_end = 16usize
        .checked_add(states)
        .and_then(|n| n.checked_add(states * 256 * 2))
        .ok_or(PrivateCertError::MalformedWire("dfa_end overflow"))?;
    wire.get(dfa_end..)
        .ok_or(PrivateCertError::MalformedWire("truncated dfa header"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn zeta_has_exact_fermat_cofactor_disequalities_and_inverse() {
        let z = zeta_c();
        let z_inv = zeta_inv_c();
        assert_eq!(z.mul(z_inv), Tower256::ONE);
        let order = (1u64 << 32) - 1;
        assert_eq!(pow_tower256(z, order), Tower256::ONE);
        for p in [3u64, 5, 17, 257, 65537] {
            assert_ne!(pow_tower256(z, order / p), Tower256::ONE);
        }
    }

    #[test]
    fn coset_encoding_folds_to_exact_mle_and_has_non_boolean_mask_coord() {
        let d = 3usize;
        let ell = 5usize;
        let (pivs, piv_invs) = compute_pivots_and_inverses(ell, d + 1).unwrap();
        let beta = unit_basis(ell);
        let offset = coset_offset(ell);

        // Verify `coset_theta_last_not_boolean`: across all `2^(ell - d)` coset points at round `d`,
        // `theta_d = dom / piv_d` is NEVER `0` and NEVER `1`!
        let dom_d = tabulate_subspace_domain(&beta, offset, ell - d, &pivs[..d]);
        for &dv in &dom_d {
            let th = dv.mul(piv_invs[d]);
            assert_ne!(th, Tower256::ZERO);
            assert_ne!(th, Tower256::ONE);
        }

        // Verify `(d + 1)`-round `evalFold` lands on the exact multilinear extension `mle(f, r)`.
        let n_full = 1usize << (d + 1);
        let table: Vec<Tower256> = (0..n_full)
            .map(|i| leaf_of_u64((i as u64) * 37 + 11))
            .collect();
        let mut word = coset_encode_table(ell, d + 1, &pivs, &piv_invs, &table);
        let r = [
            leaf_of_u64(0x1234),
            leaf_of_u64(0x5678),
            leaf_of_u64(0x9abc),
            leaf_of_u64(0xdef0),
        ];
        for j in 0..=d {
            let half = 1usize << (ell - j - 1);
            let dom_lo = tabulate_subspace_domain(&beta, offset, ell - j - 1, &pivs[..j]);
            let alpha_j = pivs[j].mul(r[j]);
            let prev = word;
            word = (0..half)
                .map(|k| {
                    let (lo, hi) = (prev[k], prev[k + half]);
                    lo.add(dom_lo[k].add(alpha_j).mul(lo.add(hi)).mul(piv_invs[j]))
                })
                .collect();
        }
        let chi = tabulate_chi(d + 1, &r);
        let expected_mle = table
            .iter()
            .zip(chi.iter())
            .fold(Tower256::ZERO, |acc, (&v, &c)| acc.add(v.mul(c)));
        assert!(word.iter().all(|&v| v == expected_mle));
    }
}
